    (close,) = _pursuit_calls(fake_beagle, "close")
    assert "tests/test_cases.py: def run_case" in " ".join(close)
    assert "Locked: tests/cases.json, tests/test_case_data.py" in result.text
    assert (project / ".beagle" / "locked").exists()


