async def test_open_on_a_locked_test_passing_without_its_module_offers_the_fix_split(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # R43 E19-E57: bind the locked test (it judges the code) and it already
    # passes (name a new test file) refused each other for 22 calls.
    project = _git_project(tmp_path, monkeypatch)
    monkeypatch.chdir(project)
    cases = '[{"in": 1, "out": 2}]'
    (project / "tests").mkdir()
    (project / "tests" / "cases.json").write_text(cases)
    (project / "tests" / "test_case_data.py").write_text(R43_GUARDED_CASES_TEST)
    _git(project, "add", "tests")
    _git(project, "commit", "-q", "-m", "T0005: Known answers")
    _store_lock(project / ".beagle", "tests/cases.json", cases)
    _store_lock(project / ".beagle", "tests/test_case_data.py", R43_GUARDED_CASES_TEST)
    check = "python3 -m pytest -q tests/test_case_data.py"
    _ready_task(fake_beagle, check)
    runtime, _ = _bound(tmp_path)

    result = await _tool(runtime, "pursuit_step").execute(
        "c1",
        {
            "task": "T0002",
            "criteria": "the codec passes",
            "done_when": check,
            "scope": ["codec.py"],
        },
    )

    assert "T0002 not opened" in result.text and "already passes" in result.text, result.text
    assert "tests/test_case_data.py imports codec (`from codec import encode`" in result.text
    assert "under `except ImportError`" in result.text
    assert "Known answers: fix tests/test_case_data.py::<what is wrong in it>" in result.text
    assert "name a new test file" not in result.text
    assert _pursuit_calls(fake_beagle, "open") == [] and _runs(fake_tau) == []

    # With the module written, the same check passing is refused as before.
    (project / "codec.py").write_text("def encode(value):\n    return value + 1\n")
    passing = await _tool(runtime, "pursuit_step").execute(
        "c2",
        {
            "task": "T0002",
            "criteria": "the codec passes",
            "done_when": check,
            "scope": ["codec.py"],
        },
    )
    assert "already passes" in passing.text and "Known answers: fix" not in passing.text


def test_unread_cases_skips_a_test_importing_no_project_code_for_earlier_locked_data(
    tmp_path: Path,
) -> None:
    module = _module()
    tests = tmp_path / "tests"
    tests.mkdir()
    (tests / "cases.json").write_text('[{"in": 1, "out": 2}]')
    (tests / "test_analysis_check.py").write_text(R42_ANALYSIS_TEST)
    (tests / "test_codec.py").write_text(
        "import codec\n\n\ndef test_codec():\n    assert codec.run(1) == 2\n"
    )
    earlier = ["tests/cases.json"]

    analysis = ["tests/test_analysis_check.py", *earlier]
    assert module._unread_cases(tmp_path, analysis, earlier=earlier) is None
    # A test that imports the code is still held to the earlier-locked data.
    judge = ["tests/test_codec.py", *earlier]
    assert module._unread_cases(tmp_path, judge, earlier=earlier) == (
        "tests/test_codec.py",
        "tests/cases.json",
    )
    # Data this task locks itself is read by its tests, as before.
    assert module._unread_cases(tmp_path, analysis) == (
        "tests/test_analysis_check.py",
        "tests/cases.json",
    )


def test_cases_test_reads_requires_the_read_to_name_the_file(tmp_path: Path) -> None:
    shapes = {
        "message string beside a bare Path(__file__)": (
            "from pathlib import Path\n\n\ndef test_cases():\n"
            '    assert Path(__file__).read_text(), "see tests/cases.json"\n',
            False,
        ),
        "named string, another file opened": (
            'import json\n\nNOTE = "cases.json"\n\n\ndef test_cases():\n'
            '    assert json.load(open("other.json"))\n',
            False,
        ),
        "open on a literal": (CASES_DATA_TEST, True),
        "read_text on a path expression": (
            "import json\nfrom pathlib import Path\n\n"
            'CASES = json.loads((Path(__file__).parent / "cases.json").read_text())\n',
            True,
        ),
        "read_text on a name assigned the path": (
            "import json\nfrom pathlib import Path\n\n"
            'CASES = Path(__file__).parent / "cases.json"\n\n\n'
            "def test_cases():\n    assert json.loads(CASES.read_text())\n",
            True,
        ),
        "open on an os.path.join name (R14)": (
            "import json\nimport os\n\n"
            'TEST_FILE = os.path.join(os.path.dirname(__file__), "cases.json")\n\n\n'
            'def test_cases():\n    with open(TEST_FILE, "r") as f:\n'
            "        assert json.load(f)\n",
            True,
        ),
    }
    for label, (source, expected) in shapes.items():
        test = tmp_path / "test_cases.py"
        test.write_text(source)
        assert _module()._cases_test_reads(test, "cases.json") is expected, label


def test_cases_test_reads_counts_path_open_and_with_as_handle(tmp_path: Path) -> None:
    # R33 E22-E32: `.open()` on a path and json.load on a with-as handle were not reads.
    head = "import json\nfrom pathlib import Path\n\nHERE = Path(__file__).parent\n"
    shapes = {
        "joinpath(...).open() with-as, json.load": (
            head + "\n\ndef test_cases():\n"
            '    with HERE.joinpath("cases.json").open() as fh:\n'
            '        assert json.load(fh)["cases"]\n',
            True,
        ),
        "name assigned the path, .open() with-as": (
            head + 'CASES = HERE / "cases.json"\n\n\ndef test_cases():\n'
            "    with CASES.open() as fh:\n        cases = json.load(fh)\n"
            "    assert cases\n",
            True,
        ),
        "read_bytes on a path": (
            head + '\n\ndef test_cases():\n    assert (HERE / "cases.json").read_bytes()\n',
            True,
        ),
        "with-as on another file, message names the data": (
            head + "\n\ndef test_cases():\n"
            '    with HERE.joinpath("other.json").open() as fh:\n'
            '        assert json.load(fh), "see cases.json"\n',
            False,
        ),
        "open() on a path not naming the data": (
            head + "\n\ndef test_cases():\n    with Path(__file__).open() as fh:\n"
            '        assert fh.read(), "cases.json"\n',
            False,
        ),
    }
    for label, (source, expected) in shapes.items():
        test = tmp_path / "test_cases.py"
        test.write_text(source)
        assert _module()._cases_test_reads(test, "cases.json") is expected, label


def _write_cases(tmp_path: Path, source: str) -> list[str]:
    (tmp_path / "tests").mkdir(exist_ok=True)
    (tmp_path / "tests" / "cases.json").write_text(R22_CASES)
    (tmp_path / "tests" / "test_cases.py").write_text(source)
    return ["tests/cases.json", "tests/test_cases.py"]


def test_cases_test_problem_names_no_collectable_test(tmp_path: Path) -> None:
    # R33: test_cases.py defined only _run_case/main helpers; pytest ran no tests.
    module = _module()
    helpers = R22_CASES_TEST.replace("def test_cases(cases):", "def _run_cases(cases):")
    stray = "\n\nclass Cases:\n    def test_x(self):\n        pass\n"
    entries = _write_cases(tmp_path, helpers + stray)
    found = module._cases_test_problem(tmp_path, entries)
    assert found is not None and found[0] == "tests/test_cases.py"
    assert "defines no test function pytest collects" in found[1]
    closing = module._cases_close_problem(tmp_path, entries)
    assert closing is not None and "defines no test function pytest collects" in closing[0]

    in_class = helpers + "\n\nclass TestCases:\n    def test_all(self, cases):\n"
    in_class += '        assert encode(b"") != cases\n'
    entries = _write_cases(tmp_path, in_class)
    assert module._cases_test_problem(tmp_path, entries) is None

    parametrized = (
        "import json\n\nimport pytest\n\nfrom cobs import encode\n\n"
        'CASES = json.load(open("tests/cases.json"))["cases"]\n\n\n'
        '@pytest.mark.parametrize("case", CASES)\ndef test_case(case):\n'
        '    assert encode(bytes.fromhex(case["input"])).hex() == case["expected"]\n'
    )
    assert module._cases_test_problem(tmp_path, _write_cases(tmp_path, parametrized)) is None


def test_cases_test_problem_names_unimported_module_name(tmp_path: Path) -> None:
    # R33 W7: test_cases.py called itc.seed(), itc.fork(), ... and never imported itc.
    module = _module()
    source = R22_CASES_TEST.replace("from cobs import encode\n", "").replace(
        "encode(bytes", "codec.encode(bytes"
    )
    found = module._cases_test_problem(tmp_path, _write_cases(tmp_path, source))
    assert found == ("tests/test_cases.py", "uses codec.encode() without importing codec")

    bound = R22_CASES_TEST + (
        "\n\ndef test_bound(cases, tmp_path):\n"
        "    for case in cases['cases']:\n        text = str(case)\n"
        "        assert text.strip() and tmp_path.exists() and int.from_bytes(b'')== 0\n"
    )
    assert module._cases_test_problem(tmp_path, _write_cases(tmp_path, bound)) is None

    imported = "import cobs as codec\n" + source
    assert module._cases_test_problem(tmp_path, _write_cases(tmp_path, imported)) is None


#: Run R40 W1's tests/test_cases.py shape: its own split_id/fork, no project import.
R40_IN_FILE_CASES_TEST = (
    "import json\n\n\n"
    "def split_id(i):\n    return [i, i]\n\n\n"
    "def fork(stamp):\n    return split_id(stamp)\n\n\n"
    "def test_cases():\n"
    '    for case in json.load(open("tests/cases.json"))["cases"]:\n'
    '        assert fork(case["input"]) == case["expected"]\n'
)


def test_cases_test_problem_flags_in_file_implementation(tmp_path: Path) -> None:
    # R40 W1: tests/test_cases.py defined split_id and fork, imported no project
    # module, and passed as the cases test.
    module = _module()
    entries = _write_cases(tmp_path, R40_IN_FILE_CASES_TEST)
    data_test = (
        "import json\n\n\ndef _valid(value):\n    return isinstance(value, str)\n\n\n"
        "def test_shape():\n"
        '    for case in json.load(open("tests/cases.json"))["cases"]:\n'
        '        assert _valid(case["expected"])\n'
    )
    (tmp_path / "tests" / "test_case_data.py").write_text(data_test)
    entries = ["tests/cases.json", "tests/test_case_data.py", *entries[1:]]

    found = module._cases_test_problem(tmp_path, entries)

    assert found == (
        "tests/test_cases.py",
        "checks its own copy of the algorithm, not the code: it defines fork and "
        "imports no module of the project",
    )
    closing = module._cases_close_problem(tmp_path, entries)
    assert closing is not None and "delete the functions it defines" in closing[1]
    # The same test importing the code is judged as before.
    imported = "import codec\n" + R40_IN_FILE_CASES_TEST
    assert module._cases_test_problem(tmp_path, _write_cases(tmp_path, imported)) is None
    # A data test whose helper is given the answers checks no copy of anything.
    assert (
        module._cases_test_problem(tmp_path, ["tests/cases.json", "tests/test_case_data.py"])
        is None
    )


#: q35 10-11's tests/test_case_data.py shape: a loader, then shape asserts on each case.
Q35_LOADER_DATA_TEST = (
    "import json\nimport pathlib\n\n\n"
    "def _load_cases():\n"
    '    return json.loads(pathlib.Path(__file__).with_name("cases.json").read_text())["cases"]\n'
    "\n\n"
    "def test_cases_shape():\n"
    "    for case in _load_cases():\n"
    '        assert "expected" in case\n'
    '        assert isinstance(case["expected"], str) and case["expected"]\n'
    '        assert case["name"]\n'
)


def test_cases_test_with_only_a_data_loader_is_not_an_own_copy(tmp_path: Path) -> None:
    # q35 10-11: test_case_data.py defined _load_cases(), imported no project
    # module, and `for case in _load_cases(): assert "result" in case` got
    # "checks its own copy of the algorithm" three closes running.
    module = _module()
    entries = _write_cases(tmp_path, Q35_LOADER_DATA_TEST)

    assert module._cases_test_problem(tmp_path, entries) is None
    # Iterating the loaded cases through a second helper computes nothing either.
    iterated = (
        Q35_LOADER_DATA_TEST.replace(
            "for case in _load_cases():", "for case in _each(_load_cases()):"
        )
        + "\n\ndef _each(cases):\n    yield from cases\n"
    )
    assert module._cases_test_problem(tmp_path, _write_cases(tmp_path, iterated)) is None


def test_cases_test_computing_results_with_own_function_is_still_an_own_copy(
    tmp_path: Path,
) -> None:
    # R40 W1 with q35's loader: the loader is not what makes it a copy; fork,
    # given each case's input, still is.
    module = _module()
    source = Q35_LOADER_DATA_TEST + (
        "\n\ndef fork(stamp):\n    return [stamp, stamp]\n\n\n"
        "def test_cases():\n"
        "    for case in _load_cases():\n"
        '        got = fork(case["input"])\n'
        '        assert got == case["expected"]\n'
    )
    found = module._cases_test_problem(tmp_path, _write_cases(tmp_path, source))
    assert found is not None and found[1].startswith("checks its own copy of the algorithm")
    # A whole case handed to the test's own function is computed from too.
    whole = R40_IN_FILE_CASES_TEST.replace('fork(case["input"])', "fork(case)")
    found = module._cases_test_problem(tmp_path, _write_cases(tmp_path, whole))
    assert found is not None and found[1].startswith("checks its own copy of the algorithm")


def test_own_copy_refusal_names_only_the_computing_functions(tmp_path: Path) -> None:
    # Audit 2026-10-12: the refusal listed every function the test called, so a
    # test with a loader read "it defines _load_cases, fork", naming the loader
    # as the copy.
    module = _module()
    source = Q35_LOADER_DATA_TEST + (
        "\n\ndef fork(stamp):\n    return [stamp, stamp]\n\n\n"
        "def test_cases():\n"
        "    for case in _load_cases():\n"
        '        got = fork(case["input"])\n'
        '        assert got == case["expected"]\n'
    )
    found = module._cases_test_problem(tmp_path, _write_cases(tmp_path, source))

    assert found is not None
    assert "it defines fork and imports no module" in found[1]
    assert "_load_cases" not in found[1]


#: q35 R51's locked tests/test_cases.py (~/itc, locked at T0002's close): it reads
#: only "operation", "node" and "new_node" of each case, and `clock.event()` then
#: `{"event": clock.event}`.
R51_CASES_TEST = (
    '"""Import from itc and validate each case in cases.json against the code."""\n\n'
    "import json\nfrom pathlib import Path\n\nimport pytest\n\n"
    'CASES_PATH = Path(__file__).with_name("cases.json")\n\n\n'
    "def _load_cases():\n"
    "    with CASES_PATH.open() as f:\n"
    '        return json.load(f)["cases"]\n\n\n'
    "def _stamp_eq(actual, expected):\n"
    '    return actual["id"] == expected["id"] and actual["event"] == expected["event"]\n\n\n'
    '@pytest.mark.parametrize("case", _load_cases(), ids=[c["name"] for c in _load_cases()])\n'
    "def test_case_create(case):\n"
    '    if case["operation"] != "create":\n'
    '        pytest.skip("not a create case")\n'
    "    from itc import IntervalTreeClock\n\n"
    '    node = case["input"]["node"]\n'
    "    clock = IntervalTreeClock(node)\n"
    '    actual = {"id": clock.id, "event": clock.event}\n'
    '    assert _stamp_eq(actual, case["expected"]), (\n'
    "        f\"{case['name']}: expected {case['expected']}, got {actual}\"\n"
    "    )\n\n\n"
    '@pytest.mark.parametrize("case", _load_cases(), ids=[c["name"] for c in _load_cases()])\n'
    "def test_case_event(case):\n"
    '    if case["operation"] != "event":\n'
    '        pytest.skip("not an event case")\n'
    "    from itc import IntervalTreeClock\n\n"
    '    node = case["input"]["node"]\n'
    "    clock = IntervalTreeClock(node)\n"
    "    clock.event()\n"
    '    actual = {"id": clock.id, "event": clock.event}\n'
    '    assert _stamp_eq(actual, case["expected"]), (\n'
    "        f\"{case['name']}: expected {case['expected']}, got {actual}\"\n"
    "    )\n\n\n"
    '@pytest.mark.parametrize("case", _load_cases(), ids=[c["name"] for c in _load_cases()])\n'
    "def test_case_subdivide(case):\n"
    '    if case["operation"] != "subdivide":\n'
    '        pytest.skip("not a subdivide case")\n'
    "    from itc import IntervalTreeClock\n\n"
    '    node = case["input"]["node"]\n'
    '    new_node = case["input"]["new_node"]\n'
    "    clock = IntervalTreeClock(node)\n"
    "    child = clock.subdivide(new_node)\n"
    "    actual = {\n"
    '        node: {"id": clock.id, "event": clock.event},\n'
    '        new_node: {"id": child.id, "event": child.event},\n'
    "    }\n"
    '    assert actual == case["expected"], (\n'
    "        f\"{case['name']}: expected {case['expected']}, got {actual}\"\n"
    "    )\n"
)


def _r51_case(name: str, operation: str, given: dict[str, Any], expected: Any) -> dict[str, Any]:
    return {
        "name": name,
        "description": f"{name} from itc2008",
        "source": "join((i1, e1), (i2, e2)) = (i1 + i2, e1 ⊔ e2).",
        "operation": operation,
        "input": given,
        "expected": expected,
    }


#: q35 R51's tests/cases.json, less the merge cases: W2 added initial_id and
#: initial_event to double_event and fork_after_event and left the test alone.
R51_CASES = [
    _r51_case("seed_stamp", "create", {"node": "A"}, {"id": "1", "event": 0}),
    _r51_case(
        "fork_seed",
        "subdivide",
        {"node": "A", "new_node": "B"},
        {"A": {"id": "1,0", "event": 0}, "B": {"id": "0,1", "event": 0}},
    ),
    _r51_case("event_on_full", "event", {"node": "A"}, {"id": "1", "event": 1}),
    _r51_case(
        "double_event",
        "event",
        {"node": "A", "initial_id": "1", "initial_event": 1},
        {"id": "1", "event": 2},
    ),
    _r51_case(
        "fork_after_event",
        "subdivide",
        {"node": "A", "new_node": "B", "initial_id": "1", "initial_event": 1},
        {"A": {"id": "1,0", "event": 1}, "B": {"id": "0,1", "event": 1}},
    ),
]


def _write_r51(tmp_path: Path, source: str, cases: list[dict[str, Any]] = R51_CASES) -> list[str]:
    (tmp_path / "tests").mkdir(exist_ok=True)
    (tmp_path / "tests" / "cases.json").write_text(json.dumps({"cases": cases}))
    (tmp_path / "tests" / "test_cases.py").write_text(source)
    return ["tests/cases.json", "tests/test_cases.py"]


def test_cases_test_problem_refuses_cases_the_test_cannot_tell_apart(tmp_path: Path) -> None:
    # q35 R51: test_case_event made one call for event_on_full and double_event,
    # which expected events 1 and 2; W4 and W5 spent 24 min on it.
    module = _module()
    ticking = R51_CASES_TEST.replace("clock.event()", "clock.tick()")

    found = module._cases_test_problem(tmp_path, _write_r51(tmp_path, ticking))

    assert found == (
        "tests/test_cases.py",
        "makes the same call in test_case_event for cases double_event and event_on_full, "
        "which expect different answers (it never reads their input keys initial_id, "
        "initial_event)",
    )
    closing = module._cases_close_problem(tmp_path, _write_r51(tmp_path, ticking))
    assert closing is not None
    assert "every input key that tells the two cases apart" in closing[1]
    # The locked file as it was is refused for the cases first.
    found = module._cases_test_problem(tmp_path, _write_r51(tmp_path, R51_CASES_TEST))
    assert found is not None and "double_event and event_on_full" in found[1]
    # Two cases agreeing on every key read are refused even with nothing unread.
    apart = [case for case in R51_CASES if "initial_id" not in case["input"]]
    twin = [*apart, _r51_case("event_twice", "event", {"node": "A"}, {"id": "1", "event": 2})]
    found = module._cases_test_problem(tmp_path, _write_r51(tmp_path, ticking, twin))
    assert found is not None
    assert "event_on_full and event_twice" in found[1]
    assert "(they agree on every input key it reads)" in found[1]

    # Reading every input key tells the cases apart; seed_stamp and
    # event_on_full share an input but not an operation, so not a call.
    reads_all = ticking.replace(
        "    clock = IntervalTreeClock(node)\n",
        '    clock = IntervalTreeClock(node, case["input"].get("initial_id", "1"),\n'
        '                              case["input"].get("initial_event", 0))\n',
    )
    assert module._cases_test_problem(tmp_path, _write_r51(tmp_path, reads_all)) is None
    # A test routing on the operation in the call, or given the whole input,
    # tells the cases apart too.
    routed = ticking.replace(
        '    if case["operation"] != "event":\n        pytest.skip("not an event case")\n', ""
    ).replace("    clock.tick()\n", '    getattr(clock, case["operation"])(**case["input"])\n')
    unpacked = ticking.replace(
        '    node = case["input"]["node"]\n    clock = IntervalTreeClock(node)\n    clock.tick()',
        '    clock = IntervalTreeClock(**case["input"])\n    clock.tick()',
    )
    events = [case for case in R51_CASES if case["operation"] == "event"]
    assert module._indistinguishable_cases(ast.parse(ticking), events) is not None
    for source in (routed, unpacked):
        assert module._indistinguishable_cases(ast.parse(source), events) is None
    # When the case goes whole to a helper, which keys reach the call is unknown.
    handed = ticking.replace("    clock.tick()\n", "    clock.tick()\n    _apply(clock, case)\n")
    assert module._indistinguishable_cases(ast.parse(handed), events) is None
    # Cases parametrized from a filtered list may never meet in one test.
    filtered = ticking.replace(
        '@pytest.mark.parametrize("case", _load_cases(),',
        '@pytest.mark.parametrize("case", [c for c in _load_cases() if c["input"]],',
    )
    assert module._indistinguishable_cases(ast.parse(filtered), events) is None


def test_method_and_value_follows_an_attribute_into_a_dict(tmp_path: Path) -> None:
    # q35 R51: `clock.event()` then `actual = {"id": clock.id, "event": clock.event}`
    # and `assert _stamp_eq(actual, case["expected"])`; W4's 61,465-char cut-off.
    module = _module()
    assert module._method_and_value(ast.parse(R51_CASES_TEST)) == "event"
    head = "def _same(a, b):\n    return a == b\n\n\ndef test_it(clock):\n    clock.event()\n"
    for value in (
        '    got = {"event": clock.event}\n    assert _same(got, {"event": 1})\n',
        "    assert [clock.event, 0] == [1, 0]\n",
        "    got = (clock.event,)\n    seen = got\n    assert seen\n",
        "    assert _same(clock.event, 1)\n",
    ):
        assert module._method_and_value(ast.parse(head + value)) == "event", value
    for method in (
        "    handler = clock.event\n    handler()\n",
        "    assert callable(clock.event)\n",
        '    handlers = {"event": clock.event}\n    handlers["event"]()\n',
        "    assert list(map(clock.event, [1])) == [2]\n",
        '    got = {"event": other.event}\n    assert _same(got, {"event": 1})\n',
    ):
        assert module._method_and_value(ast.parse(head + method)) is None, method
    # Through the close: cases the test can tell apart, and .event both ways.
    apart = [case for case in R51_CASES if "initial_id" not in case["input"]]
    found = module._cases_test_problem(tmp_path, _write_r51(tmp_path, R51_CASES_TEST, apart))
    assert found is not None
    assert found[1].startswith("uses .event both as a method, .event(), and as a value")


ITC_REFERENCE = (
    "Interval Tree Clocks\n\n4\n\n"
    "fork(i) = (i1, i2), where (i1, i2) = split(i)\n"
    "join((i1, e1), (i2, e2)) = (sum(i1, i2), join(e1, e2))\n"
    "event((i, e)) = (i, fill(i, e)) if fill(i, e) != e\n"
    "norm((0, 0)) = 0 and norm((1, 1)) = 1\n"
)


def _cases_with_reference(
    tmp_path: Path, fake_beagle: Path, monkeypatch: pytest.MonkeyPatch, cases: list[Any]
) -> Path:
    """A known-answers task writing `cases`, in a project with references/itc2008.txt."""
    project = _cases_task(tmp_path, fake_beagle, monkeypatch, CASES_DATA_TEST)
    refs = project / "references"
    refs.mkdir()
    (refs / "itc2008.txt").write_text(ITC_REFERENCE)
    writes = json.loads(os.environ["FAKE_TAU_WRITES"])
    writes["tests/cases.json"] = json.dumps(cases)
    monkeypatch.setenv("FAKE_TAU_WRITES", json.dumps(writes))
    return project


