_FULL = "\u2588\u2588\u2588\u2588"
#: R36's references/interval-tree-clocks.txt, lines 74-86, verbatim.
R36_REFERENCE = (
    f"The user writes the data to A, which creates ID 1 = {_FULL}, increments the counter "
    f"to 1 = {_FULL} also.\n"
    "\n"
    "A synchronizes with B by forking the stamp, giving IDs {1,0} = "
    "\u2588\u2588\u2592\u2592 and {0,1} = \u2592\u2592\u2588\u2588. "
    f"The counter remains 1 = {_FULL}.\n"
    "\n"
    "The user writes data to B, which increments B's counter to {0,2}.\n"
    "\n"
    "Then we're able to sync. The problem happens whenever we swap steps 2 and 3 however:\n"
    "\n"
    f"The user writes the data to A, which creates ID 1 = {_FULL}, increments the counter "
    f"to 1 = {_FULL} also.\n"
    "\n"
    f"The user writes data to B, which creates ID 1 = {_FULL}, increments the counter to "
    f"1 = {_FULL} also.\n"
    "\n"
    "The system can only assume both data sets are equivalent since the clocks are the same.\n"
)
#: R36's final tests/cases.json (W2-W4): a file:line label, then the quote in parentheses.
R36_CASES = [
    {
        "description": "Identity local update",
        "input": {"id": "A", "event": 1, "remote_event": None},
        "expected": {"id": "A", "event": 2, "remote_event": None},
        "source": "interval-tree-clocks.txt:114 (The user writes the data to A, which "
        f"creates ID 1 = {_FULL})",
    },
    {
        "description": "Remote update with higher event",
        "input": {"id": "A", "event": 1, "remote_event": {"id": "B", "event": 5}},
        "expected": {"id": "A", "event": 2, "remote_event": {"id": "B", "event": 5}},
        "source": f"interval-tree-clocks.txt:115 (The counter remains 1 = {_FULL})",
    },
    {
        "description": "Remote update with lower event",
        "input": {"id": "A", "event": 10, "remote_event": {"id": "B", "event": 5}},
        "expected": {"id": "A", "event": 11, "remote_event": {"id": "B", "event": 5}},
        "source": "interval-tree-clocks.txt:116 (The user writes data to B, which increments "
        "B's counter to {0,2})",
    },
    {
        "description": "Merge and conflict detection",
        "input": {"id": "A", "event": 1, "remote_event": {"id": "B", "event": 1}},
        "expected": {"id": "A", "event": 2, "remote_event": {"id": "B", "event": 1}},
        "source": "interval-tree-clocks.txt:118 (The system can only assume both data sets "
        "are equivalent since the clocks are the same.)",
    },
]


def _r36_project(tmp_path: Path, cases: list[Any]) -> Path:
    (tmp_path / "references").mkdir()
    (tmp_path / "references" / "interval-tree-clocks.txt").write_text(
        R36_REFERENCE, encoding="utf-8"
    )
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "cases.json").write_text(json.dumps(cases), encoding="utf-8")
    return tmp_path


def test_quotes_reference_finds_parenthesised_quote_after_file_line_label(
    tmp_path: Path,
) -> None:
    # Run R36: W2-W4 wrote every source this way; the check flagged all 4.
    module = _module()
    reference = module._normalised(R36_REFERENCE)
    for case in R36_CASES:
        assert module._quotes_reference(case["source"], reference), case["source"]
    assert module._quotes_reference(
        "refs.txt:116 [The user writes data to B, which increments B's counter to {0,2}]",
        reference,
    )
    assert module._quotes_reference(
        "refs.txt:118 The system can only assume both data sets are equivalent", reference
    )
    assert not module._quotes_reference(
        "refs.txt:116 (The user writes data to C, which increments it)", reference
    )
    project = _r36_project(tmp_path, R36_CASES)
    found = module._unquoted_cases(project, ["tests/cases.json"])
    # The quotes are found; what still flags cases is their results (T0314).
    assert found is not None and found[4] is True


def test_quoted_context_finds_parenthesised_quote() -> None:
    module = _module()
    lines = [module._normalised(line) for line in R36_REFERENCE.splitlines() if line.strip()]
    context = module._quoted_context(R36_CASES[2]["source"], lines)
    assert context == [
        "the user writes data to b, which increments b's counter to {0,2}.",
        "then we're able to sync. the problem happens whenever we swap steps 2 and 3 however:",
    ]
    assert module._lines_after(R36_CASES[2]["source"], lines) == context[1:]


def test_bare_file_line_source_still_flagged_unquoted(tmp_path: Path) -> None:
    # Run R36's first verdict, on W1's bare labels, was right and stays so.
    module = _module()
    reference = module._normalised(R36_REFERENCE)
    assert not module._quotes_reference("refs.txt:12", reference)
    assert not module._quotes_reference("interval-tree-clocks.txt:114", reference)
    assert [m.group(0) for m in module._QUOTE_MARKS.finditer("refs.txt:12 [0] (1, 2)")] == []
    bare = [{**case, "source": case["source"].split(" (")[0]} for case in R36_CASES]
    found = module._unquoted_cases(_r36_project(tmp_path, bare), ["tests/cases.json"])
    assert found == (
        "tests/cases.json",
        4,
        4,
        ["#1", "#2", "#3"],
        False,
        [
            ("#1", "interval-tree-clocks.txt:114"),
            ("#2", "interval-tree-clocks.txt:115"),
            ("#3", "interval-tree-clocks.txt:116"),
        ],
        [],
    )


def test_case_results_drops_fields_equal_to_nested_inputs() -> None:
    # Run R36: each expected dict echoed the nested input id "A" (and "B", 5)
    # beside the one event it changed; only the changed event is an answer.
    module = _module()
    assert [module._case_results(case) for case in R36_CASES] == [
        [(2, True)],
        [(2, True)],
        [(11, True)],
        [(2, True)],
    ]
    nested = {
        "input": {"ops": [{"peer": "left side", "n": [1, 2]}], "flag": True},
        "expected": {"peer": "left side", "n": [1, 2], "count": 1, "total": "three nine"},
    }
    assert module._case_results(nested) == [(1, True), ("three nine", False)]
    # Every result equal to an input: none is dropped, each is narrow (R34, R35).
    echo = {"input": {"data": "00 11 00"}, "expected": {"data": "00 11 00"}}
    assert module._case_results(echo) == [("00 11 00", True)]


def test_result_unquoted_requires_each_changed_field(tmp_path: Path) -> None:
    # Run R36: "A" was in every quoted line, so one echoed field passed each
    # case. Cases #1, #3 and #4 give an event that is in neither the quoted line
    # nor the next one; case #2's event 2 is only inside "{0,2}" on the next.
    module = _module()
    lines = [module._normalised(line) for line in R36_REFERENCE.splitlines() if line.strip()]
    for case in R36_CASES:
        assert module._result_unquoted(case, [lines]), case["description"]
    found = module._unquoted_cases(_r36_project(tmp_path, R36_CASES), ["tests/cases.json"])
    assert found is not None
    assert found[:5] == ("tests/cases.json", 4, 4, ["#1", "#2", "#3"], True)
    # Two changed fields, one on the quoted line and one nowhere near it.
    half = {
        "input": {"id": "B", "event": 0},
        "expected": {"id": "B", "event": 2, "peers": 11},
        "source": "interval-tree-clocks.txt:116 (The user writes data to B, which "
        "increments B's counter to {0,2})",
    }
    assert module._result_unquoted(half, [lines])


def test_result_unquoted_flags_all_four_r36_wrong_cases(tmp_path: Path) -> None:
    # Audit 11: case #2 quotes "The counter remains 1" for an event of 2, and
    # passed on the 2 inside "{0,2}" on the line after its quote.
    module = _module()
    lines = [module._normalised(line) for line in R36_REFERENCE.splitlines() if line.strip()]
    flagged = [
        f"#{i + 1}" for i, case in enumerate(R36_CASES) if module._result_unquoted(case, [lines])
    ]
    assert flagged == ["#1", "#2", "#3", "#4"]
    found = module._unquoted_cases(_r36_project(tmp_path, R36_CASES), ["tests/cases.json"])
    assert found is not None and found[1:5] == (4, 4, ["#1", "#2", "#3"], True)


def test_narrow_result_inside_a_larger_token_on_next_line_is_not_found() -> None:
    # T0293's line after a quote holds a narrow result only as a whole value.
    module = _module()
    lines = ["the counter remains 1.", "b's counter goes to {0,2}, then (1, 2)."]
    for event in (0, 1, 2, "2"):
        case = {
            "input": {"id": "A"},
            "expected": {"event": event},
            "source": "'the counter remains 1'",
        }
        assert module._result_unquoted(case, [lines]) == (event != 1), event
    for after in ("then it is 2.", "event = 2", "event: 2;", "{2}", "[0, 2] ... 2"):
        case = {"input": {"id": "A"}, "expected": {"event": 2}, "source": "'the counter remains 1'"}
        assert not module._result_unquoted(case, [[lines[0], after]]), after
    for after in ("event 12", "2nd", "v2", "[0,2]", "(1; 2)", "{ 2 , 0 }"):
        case = {"input": {"id": "A"}, "expected": {"event": 2}, "source": "'the counter remains 1'"}
        assert module._result_unquoted(case, [[lines[0], after]]), after
    # The quoted line itself keeps T0293's rule: its "{0,2}" holds 2.
    quoted = {"input": {"id": "A"}, "expected": {"event": 2}, "source": "'goes to {0,2}'"}
    assert not module._result_unquoted(quoted, [lines[::-1]])
    assert module._renders_result("{0,2}", 2) and not module._renders_result("{0,2}", 2, whole=True)
    assert module._renders_result("44", "44", whole=True)
    assert not module._renders_result("344", "44", whole=True)


def test_result_unquoted_requires_a_nested_result_not_one_scalar() -> None:
    # Run R44: fork_of_seed's nested id was not searched, so its counter 0
    # alone passed it against a quote that gives another nested value.
    module = _module()
    lines = [
        "half = ((0, 0.5), (0.5, 1)), the counter stays 0.",
        "split(1) = ((1, 0), (0, 1)), the counter stays 0.",
    ]
    source = "split(1) = ((1, 0), (0, 1)),"
    wrong = {
        "name": "fork_of_seed",
        "input": {"id": 1},
        "expected": {"id": [[0, 0.5], [0.5, 1]], "counter": 0, "ok": True},
        "source": source,
    }
    assert module._result_unquoted(wrong, [lines])
    swapped = {**wrong, "expected": {"id": [[0, 1], [1, 0]], "counter": 0}}
    assert module._result_unquoted(swapped, [lines])
    right = {**wrong, "expected": {"id": [[1, 0], [0, 1]], "counter": 0, "ok": True}}
    assert not module._result_unquoted(right, [lines])
    halves = {**wrong, "source": "half = ((0, 0.5), (0.5, 1)),"}
    assert not module._result_unquoted(halves, [lines])
    assert module._renders_result("[[0, 0.5], [0.5, 1]]", [[0, 0.5], [0.5, 1]])
    assert not module._renders_result("(0, 0.5), (0.5, 1), (1, 2)", [[0, 0.5], [0.5, 1]])
    assert not module._renders_result("0.5, 1", [[0, 0.5], [0.5, 1]])
    assert not module._searchable_result([[0, "a"]])


def test_keep_sourced_omits_a_case_with_no_searchable_result(tmp_path: Path) -> None:
    # Run R44: causality_conflict_detection expected `true`, had nothing to
    # search, and was listed as sourced for later workers to keep.
    module = _module()
    quote = "split(1) = ((1, 0), (0, 1)), the counter stays 0."
    (tmp_path / "references").mkdir()
    (tmp_path / "references" / "ref.txt").write_text(f"Splitting.\n{quote}\nThe end.\n")
    cases = [
        {"name": "kept", "input": {"id": 1}, "expected": [[1, 0], [0, 1]], "source": quote},
        {"name": "bare", "input": {"id": 1}, "expected": True, "source": quote},
        {"name": "empty", "input": {"id": 1}, "expected": None, "source": quote},
        {"name": "wrong", "input": {"id": 1}, "expected": [[0, 1], [1, 0]], "source": quote},
    ]
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "cases.json").write_text(json.dumps(cases))
    lines = [module._normalised(quote)]
    assert module._result_found(cases[1], [lines]) is None
    assert not module._result_unquoted(cases[1], [lines])
    found = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert found is not None
    assert found[1:5] == (1, 4, ["wrong"], True)
    assert found[6] == ["kept"]
    assert module._keep_sourced(found[6]) == "Already sourced, keep unchanged: kept."


def test_result_unquoted_passes_when_each_changed_field_quoted(tmp_path: Path) -> None:
    module = _module()
