def test_r15_full_cases_file_all_quote_the_reference(tmp_path: Path) -> None:
    module = _module()
    cases = json.loads(R15_FULL_CASES_JSON)
    assert len(cases) == 32
    refs = tmp_path / "references"
    refs.mkdir()
    texts = []
    for name, lines in R15_QUOTED_REFERENCE_LINES.items():
        text = "\n".join(lines[n] for n in sorted(lines)) + "\n"
        (refs / name).write_text(text, encoding="utf-8")
        texts.append(module._normalised(text))
    unfound = [
        module._case_label(case, i)
        for i, case in enumerate(cases)
        if not any(
            module._quotes_reference(s, text)
            for s in module._source_strings(case)
            for text in texts
        )
    ]
    assert unfound == []
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "cases.json").write_text(R15_FULL_CASES_JSON, encoding="utf-8")
    # Run R44: the nested results are judged whole, and most of these prose
    # quotes do not give them; the one quoting "(1, 0)" stays sourced.
    found = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert found is not None and found[4] is True
    assert found[6] == ["seed-stamp-is-one"]


def test_known_answers_guidance_asks_for_a_quoted_source(tmp_path: Path) -> None:
    module = _module()
    assert "quoting the reference's own words verbatim" in module.CASES_FIRST_NOTE
    assert "references/*.txt" in module.CASES_FIRST_NOTE
    refs = tmp_path / "references"
    refs.mkdir()
    (refs / "itc2008.txt").write_text(ITC_REFERENCE)
    (refs / "index.json").write_text(
        json.dumps(
            {"request": "ITC in Python", "fetched": {"itc2008.txt": "https://e.org/itc.pdf"}}
        )
    )
    data_brief = module._references_brief(tmp_path, context_only=True)
    assert module.QUOTED_SOURCE_NOTE in data_brief
    assert "quotes, verbatim, the line of references/*.txt" in data_brief
    assert "is not a source" in data_brief
    assert module.QUOTED_SOURCE_NOTE not in module._references_brief(tmp_path)


def test_references_brief_states_line_counts_and_read_cost(tmp_path: Path) -> None:
    module = _module()
    window = module.WINDOW_LINES
    refs = tmp_path / "references"
    refs.mkdir()
    (refs / "long.txt").write_text("".join(f"line {i}\n" for i in range(2 * window + 1)))
    (refs / "short.txt").write_text("one\ntwo\nthree")
    (refs / "index.json").write_text(
        json.dumps(
            {
                "request": "x",
                "fetched": {"long.txt": "https://e.org/a", "short.txt": "https://e.org/b"},
            }
        )
    )
    brief = module._references_brief(tmp_path)
    per = f"at {window} lines per read"
    long_line = f"(from https://e.org/a) — {2 * window + 1} lines, 3 reads {per}"
    assert f"references/long.txt {long_line}" in brief
    assert f"references/short.txt (from https://e.org/b) — 3 lines, 1 read {per}" in brief
    assert "by line range" not in brief
    assert "by line range" in module._references_brief(tmp_path, context_only=True)


def test_references_brief_says_how_to_search_references(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R40: workers re-read whole references 6-20 times and still invented values.
    module = _module()
    refs = tmp_path / "references"
    refs.mkdir()
    (refs / "paper.txt").write_text("the value is 42\n")
    (refs / "index.json").write_text(
        json.dumps({"request": "x", "fetched": {"paper.txt": "https://e.org/p"}})
    )
    real = shutil.which
    monkeypatch.setattr(
        module.shutil, "which", lambda name, *a, **k: "/bin/tilth" if name == "tilth" else None
    )
    brief = module._references_brief(tmp_path, context_only=True)
    tilth = 'tilth "<words>" --scope references'
    assert module._reference_search() == tilth
    assert f"{module.QUOTED_SOURCE_NOTE} To find the line that gives a value" in brief
    assert f"`{tilth}`, rather than reading the reference through." in brief
    assert tilth not in module._references_brief(tmp_path)

    monkeypatch.setattr(
        module.shutil, "which", lambda name, *a, **k: None if name == "tilth" else real(name)
    )
    grep = 'grep -n -i -F "<words>" references/*.txt'
    assert module._reference_search() == grep
    fallback = module._references_brief(tmp_path, context_only=True)
    assert f"`{grep}`, rather than reading the reference through." in fallback
    assert "tilth" not in fallback


def test_known_answers_brief_has_worked_example(tmp_path: Path) -> None:
    # R34-R40: workers quoted the input or a rule line and invented expected values.
    module = _module()
    refs = tmp_path / "references"
    refs.mkdir()
    (refs / "paper.txt").write_text("the value is 42\n")
    (refs / "index.json").write_text(
        json.dumps({"request": "x", "fetched": {"paper.txt": "https://e.org/p"}})
    )
    example = module._worked_example_note()
    brief = module._references_brief(tmp_path, context_only=True)
    assert example in brief
    assert brief.index(module.QUOTED_SOURCE_NOTE) < brief.index(example)
    for line in module.WORKED_EXAMPLE_LINES:
        assert line in example
    right = json.dumps(module.WORKED_EXAMPLE_CASE)
    assert f"Right (copied from the line that gives the result): {right}" in example
    wrong = json.dumps(module.WORKED_COUNTER_CASE)
    assert f'Wrong (that rule line does not give "cab"): {wrong}' in example
    assert example not in module._references_brief(tmp_path)

    failed = {"request": "x", "failed": {"https://e.org/p": "404"}}
    (refs / "index.json").write_text(json.dumps(failed))
    unfetched = module._references_brief(tmp_path, context_only=True)
    assert "could not fetch https://e.org/p: 404" in unfetched
    assert example not in unfetched


def test_worked_example_agrees_with_the_source_judge(tmp_path: Path) -> None:
    module = _module()
    refs = tmp_path / "references"
    refs.mkdir()
    (refs / "guide.txt").write_text("\n".join(module.WORKED_EXAMPLE_LINES) + "\n")
    tests = tmp_path / "tests"
    tests.mkdir()
    cases = tests / "cases.json"
    example = module.WORKED_EXAMPLE_CASE
    assert example["source"] in module.WORKED_EXAMPLE_LINES
    assert example["source"] != module.WORKED_COUNTER_CASE["source"]

    cases.write_text(json.dumps([example]))
    assert module._unquoted_cases(tmp_path, ["tests/cases.json"]) is None

    cases.write_text(json.dumps([module.WORKED_COUNTER_CASE]))
    flagged = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert flagged is not None
    assert flagged[4] is True
    assert flagged[3] == [module.WORKED_COUNTER_CASE["name"]]


def test_a_witness_block_is_read_from_the_end_of_a_report() -> None:
    witness = _module()._witness
    assert witness(WITNESSED_REPORT) == ("src/clock.py", "    return a + b", "    return a - b")
    multi = "WITNESS: `a.py`\nNEEDLE:\nif x:\n    y()\nREPLACEMENT:\nEND WITNESS"
    assert witness(multi) == ("a.py", "if x:\n    y()", "")
    assert witness("no witness here") is None
    assert witness("WITNESS: a.py\nNEEDLE:\n\nREPLACEMENT:\nx\nEND WITNESS") is None


@pytest.mark.anyio
async def test_a_worker_with_no_report_gets_a_short_stub_not_its_event_stream(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # Run 7: a worker ended on `length` with no text, and its whole stdout --
    # 822 MB of message_update events -- became the step's result.
    project = _pursuit_project(tmp_path)
    monkeypatch.chdir(project)
    monkeypatch.setenv("FAKE_TAU_RAMBLES", "1")
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)

    result = await _tool(runtime, "pursuit_step").execute(
        "c1",
        {
            "task": "T0002",
            "criteria": "done.txt exists",
            "done_when": "grep -q done done.txt",
            "scope": ["done.txt"],
        },
    )

    assert len(result.text) < 20_000
    assert "wrote no report: it ended on stopReason=length" in result.text
    assert result.text.count("so the parser") == 1  # the tail of its thinking
    [run, *_] = _runs(fake_tau)
    session_id = run["argv"][run["argv"].index("--session-id") + 1]
    assert f"{session_id}.jsonl" in result.text
    [close] = _pursuit_calls(fake_beagle, "close")
    assert "Worker transcript" not in close[close.index("--body") + 1]


@pytest.mark.anyio
async def test_a_step_locks_its_cases_and_later_steps_cannot_change_them(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    project = _pursuit_project(tmp_path)
    monkeypatch.chdir(project)
    (project / "cases.json").write_text('[{"in": 1, "out": 2}]')
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)
    step = _tool(runtime, "pursuit_step")

    first = await step.execute(
        "c1",
        {
            "task": "T0002",
            "criteria": "the cases are written",
            "done_when": "grep -q done done.txt",
            "locks": ["cases.json", "missing.json"],
        },
    )

    # R17: a lock entry not on disk is the work left, not a note after the close.
    assert "missing.json: it is locked for this task and not written" in first.text
    assert not (project / ".beagle" / "locked").exists()
    (project / "missing.json").write_text("[]")
    (fake_beagle / "next.out").write_text(json.dumps({"open": ["T0002"], "ready": []}))
    first = await step.execute("c1b", {"task": "T0002"})
    assert "Locked: cases.json, missing.json" in first.text
    assert (project / ".beagle" / "locked" / "cases.json").read_text() == '[{"in": 1, "out": 2}]'

    # A later worker that rewrites the cases has them put back before the check.
    (project / "done.txt").unlink()
    monkeypatch.setenv("FAKE_TAU_TAMPERS", "cases.json")
    second = await step.execute(
        "c2", {"task": "T0002", "criteria": "the code passes", "done_when": "grep -q done done.txt"}
    )

    assert (project / "cases.json").read_text() == '[{"in": 1, "out": 2}]'
    assert "changed locked files (cases.json)" in second.text
    assert "Locked files:" in _runs(fake_tau)[-1]["stdin"]
    assert "- cases.json" in _runs(fake_tau)[-1]["stdin"]


