@pytest.mark.anyio
async def test_step_and_dispatch_timeout_clamped(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # R01: the driver raised a worker's timeout to 1800 s, which bought only a longer spiral.
    module = _module()
    timeout, note = module._worker_timeout(1800)
    assert timeout == module.DEFAULT_DISPATCH_TIMEOUT == 900.0
    assert "clamped to 900s" in note
    assert module._worker_timeout(300) == (300.0, "")
    assert module._worker_timeout(None) == (module.DEFAULT_DISPATCH_TIMEOUT, "")
    assert module._worker_timeout("soon") == (module.DEFAULT_DISPATCH_TIMEOUT, "")

    monkeypatch.chdir(_pursuit_project(tmp_path))
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)
    stepped = await _tool(runtime, "pursuit_step").execute(
        "c1",
        {
            "task": "T0002",
            "criteria": "done.txt exists",
            "done_when": "grep -q done done.txt",
            "scope": ["done.txt"],
            "timeout": 3600,
        },
    )
    assert stepped.text.startswith("(timeout 3600s was clamped to 900s")
    assert "closed done" in stepped.text

    bare = tmp_path / "bare"
    bare.mkdir()
    dispatch = _tool(runtime, "pursuit_dispatch")
    dispatched = await dispatch.execute(
        "c2", {"brief": "Write notes", "cwd": str(bare), "timeout": 1800}
    )
    assert dispatched.text.startswith("(timeout 1800s was clamped to 900s")
    assert "[pursuit_dispatch] step-executor" in dispatched.text
    unclamped = await dispatch.execute(
        "c3", {"brief": "Write notes", "cwd": str(bare), "timeout": 600}
    )
    assert "clamped" not in unclamped.text


#: A builtin catalog model with a known max_tokens (64000).
_HAIKU = {"model": "claude-haiku-4-5", "provider": "anthropic"}


@pytest.mark.anyio
async def test_worker_wall_scales_with_max_tokens_and_measured_rate(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # q38fn 10-11: 5 of 9 workers were killed at 900 s at ~20 tok/s with max_tokens 16384.
    project = tmp_path / "project"
    project.mkdir()
    monkeypatch.chdir(project)
    runtime, _ = _bound(tmp_path)
    module = _loaded_module()
    assert module._model_max_tokens(**_HAIKU) == 64000
    dispatch = _tool(runtime, "pursuit_dispatch")
    monkeypatch.setenv("FAKE_TAU_DECODE", "2000,100000")  # 20 tok/s after the first output
    await dispatch.execute("c1", {"brief": "Write notes", **_HAIKU})

    assert module._decode_rate(project, **_HAIKU) == 20.0
    assert module._worker_wall(project, **_HAIKU) == 3 * 64000 / 20 == 9600
    assert module._worker_wall(project, "gpt-4o", "openai") == 900  # nothing measured on it
    asked = {"brief": "Write notes", **_HAIKU}
    clamped = await dispatch.execute("c2", {**asked, "timeout": 99999})
    assert clamped.text.startswith("(timeout 99999s was clamped to 9600s")
    unclamped = await dispatch.execute("c3", {**asked, "timeout": 5000})
    assert "clamped" not in unclamped.text

    _pursuit_project(tmp_path)
    _ready_task(fake_beagle)
    (project / "done.txt").unlink()  # the dispatches' fake worker wrote it
    timeouts: list[float] = []
    real_run_worker = module._run_worker

    async def recording_run_worker(*args: Any, **kwargs: Any) -> Any:
        timeouts.append(args[4])
        return await real_run_worker(*args, **kwargs)

    monkeypatch.setattr(module, "_run_worker", recording_run_worker)
    step = _tool(runtime, "pursuit_step")
    stepped = await step.execute(
        "c4",
        {
            "task": "T0002",
            "criteria": "c",
            "done_when": "grep -q done done.txt",
            "timeout": 99999,
            **_HAIKU,
        },
    )
    assert timeouts == [9600]
    assert stepped.text.startswith("(timeout 99999s was clamped to 9600s")
    assert "closed done" in stepped.text


@pytest.mark.anyio
async def test_worker_wall_default_unchanged_without_a_measured_rate(
    tmp_path: Path, beagle: Path, fake_tau: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    project = tmp_path / "project"
    project.mkdir()
    monkeypatch.chdir(project)
    runtime, _ = _bound(tmp_path)
    module = _loaded_module()
    dispatch = _tool(runtime, "pursuit_dispatch")
    assert module._worker_wall(project, **_HAIKU) == module.DEFAULT_DISPATCH_TIMEOUT == 900.0

    # Turns with no timing measure no rate.
    await dispatch.execute("c1", {"brief": "Write notes", **_HAIKU})
    assert module._decode_rate(project, **_HAIKU) is None
    clamped = await dispatch.execute("c2", {"brief": "Write notes", "timeout": 1800, **_HAIKU})
    assert clamped.text.startswith("(timeout 1800s was clamped to 900s")

    # A rate on a model tau knows no max_tokens for keeps the default.
    monkeypatch.setenv("FAKE_TAU_DECODE", "2000,100000")
    unknown = {"model": "no-such-model", "provider": "anthropic"}
    await dispatch.execute("c3", {"brief": "Write notes", **unknown})
    assert module._decode_rate(project, **unknown) == 20.0
    assert module._model_max_tokens(**unknown) is None
    assert module._worker_wall(project, **unknown) == 900.0

    # Too few tokens measured is no rate yet; a fast model's wall stays at the floor.
    monkeypatch.setenv("FAKE_TAU_DECODE", "500,100000")
    await dispatch.execute("c4", {"brief": "Write notes", **_HAIKU})
    assert module._decode_rate(project, **_HAIKU) is None
    monkeypatch.setenv("FAKE_TAU_DECODE", "100000,1000")
    await dispatch.execute("c5", {"brief": "Write notes", **_HAIKU})
    assert module._decode_rate(project, **_HAIKU) == 100500 * 1000 / 101000
    assert module._worker_wall(project, **_HAIKU) == 900.0


# --------------------------------------------------------------------------- #
# run R02: an unprovable task re-stepped, milestones abandoned, a stalled stop
# --------------------------------------------------------------------------- #


def _witnessed_pursuit(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    project = _git_project(tmp_path, monkeypatch)
    with (project / ".beagle" / "pursuit.toml").open("a", encoding="utf-8") as goal:
        goal.write('\n[close]\nrequire = "witness"\n')
    return project


@pytest.mark.anyio
async def test_unprovable_restep_spawns_no_worker(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # R02: T0003's scope held tests only, so `prove` had no source file to take
    # away; six steps sent two workers each at the same passing check.
    monkeypatch.chdir(_witnessed_pursuit(tmp_path, monkeypatch))
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)
    step = _tool(runtime, "pursuit_step")
    args = {
        "task": "T0002",
        "criteria": "c",
        "done_when": "grep -q done done.txt",
        "scope": ["tests"],
    }

    first = await step.execute("c1", args)
    record = {"id": "T0002", "title": "Parser", "status": "open"}
    record |= {"done_when": "grep -q done done.txt", "scope": ["tests"]}
    (fake_beagle / "show.out").write_text(json.dumps(record))
    (fake_beagle / "next.out").write_text(json.dumps({"open": [{"id": "T0002"}], "ready": []}))
    again = await step.execute("c2", {"task": "T0002"})
    same = await step.execute("c3", {"task": "T0002", "done_when": "grep -q done done.txt"})

    assert len(_runs(fake_tau)) == 1
    assert "no defect could be put back" in first.text and "stays open" in first.text
    for refused in (again, same):
        assert "not run — call instead: " in refused.text
        assert "This check already passes and cannot be shown to refuse" in refused.text
        # R12: a tests-only scope with no data file proves through the module it imports.
        assert "mutate the module the test imports" in refused.text
        assert "the data file's absence is the proof" not in refused.text
        assert "import the code" not in refused.text
    assert _pursuit_calls(fake_beagle, "close") == []


@pytest.mark.anyio
async def test_unprovable_first_verdict_stops_attempts(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # R02 ran the second worker of a step after its check already passed.
    monkeypatch.chdir(_git_project(tmp_path, monkeypatch))
    monkeypatch.setenv("FAKE_TAU_REPORT", WITNESSED_REPORT)
    _ready_task(fake_beagle)
    (fake_beagle / "prove.out").write_text("T0002: NOT PROVEN — src/clock.py is not there\n")
    (fake_beagle / "prove.rc").write_text("9")
    runtime, _ = _bound(tmp_path)

    result = await _tool(runtime, "pursuit_step").execute(
        "c1",
        {
            "task": "T0002",
            "criteria": "c",
            "done_when": "grep -q done done.txt",
            "scope": ["done.txt"],
            "attempts": 3,
        },
    )

    assert len(_runs(fake_tau)) == 1
    # One verdict: the witness, then the changed source taken away.
    assert [p[1] for p in _pursuit_calls(fake_beagle, "prove")] == ["--mutate", "--absent"]
    assert _pursuit_calls(fake_beagle, "close") == []
    assert "no defect could be put back" in result.text
    assert "must import the code this task tests" in result.text


