async def _hung_second_worker(
    tmp_path: Path,
    fake_beagle: Path,
    monkeypatch: pytest.MonkeyPatch,
    length_stops: int,
    cut_offs: int = 0,
    timeout: int = 3,
) -> str:
    project = _git_project(tmp_path, monkeypatch)
    monkeypatch.chdir(project)
    monkeypatch.setenv("FAKE_TAU_SUCCEEDS_ON", "99")
    monkeypatch.setenv("FAKE_TAU_HANGS_ON", "2")
    monkeypatch.setenv("FAKE_TAU_LENGTH_STOPS", str(length_stops))
    monkeypatch.setenv("FAKE_TAU_CUT_OFFS", str(cut_offs))
    monkeypatch.setenv("FAKE_TAU_WRITES", json.dumps({"tests/test_x.py": "def test_x(): ...\n"}))
    monkeypatch.setenv("FAKE_TAU_REPORT", "attempt 1: wrote tests/test_x.py; the check fails")
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)
    result = await _tool(runtime, "pursuit_step").execute(
        "c1",
        {
            "task": "T0002",
            "criteria": "c",
            "done_when": "grep -q done done.txt",
            "scope": ["done.txt", "tests/test_x.py"],
            "timeout": timeout,
        },
    )
    return str(result.text)


@pytest.mark.anyio
async def test_second_worker_timeout_keeps_the_first_attempts_report_and_check(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # Run R15: W6 was killed at the wall, and W5's report and the check's output went with it.
    text = await _hung_second_worker(tmp_path, fake_beagle, monkeypatch, 0)

    assert len(_runs(fake_tau)) == 2
    assert "exceeded its wall-clock budget of 3s" in text and "stays open" in text
    assert "The attempt before it reported:\nattempt 1: wrote tests/test_x.py" in text
    assert "exit 2 after that attempt:\ngrep: done.txt: No such file" in text
    assert "Changed or new in its scope: tests/test_x.py" in text
    assert "turn cap" not in text and "output limit" not in text
    assert "the files it changed go into the next brief on T0002" in text
    assert _pursuit_calls(fake_beagle, "close") == []


@pytest.mark.anyio
async def test_killed_worker_progress_reaches_the_next_attempts_notes(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # q38fn 10-11: a4f69dee was killed at 900 s with ~7 min of reasoning in flight;
    # only the driver's hand-copied notes carried such reasoning to the next worker.
    project = _git_project(tmp_path, monkeypatch)
    monkeypatch.chdir(project)
    monkeypatch.setenv("FAKE_TAU_SUCCEEDS_ON", "99")
    monkeypatch.setenv("FAKE_TAU_HANGS_ON", "1")
    monkeypatch.setenv("FAKE_TAU_MIDTURN", "x" * 5000 + " so case 3 encodes as (1, 0)")
    monkeypatch.setenv("FAKE_TAU_WRITES", json.dumps({"tests/test_x.py": "def test_x(): ...\n"}))
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)
    step = _tool(runtime, "pursuit_step")
    args = {
        "task": "T0002",
        "criteria": "c",
        "done_when": "grep -q done done.txt",
        "scope": ["done.txt", "tests/test_x.py"],
    }

    killed = (await step.execute("c1", {**args, "timeout": 3})).text
    assert "exceeded its wall-clock budget of 3s and was killed." in killed
    assert "turn cap" not in killed and "Split the task" not in killed
    assert "What it said last and the files it changed go into the next brief on T0002" in killed

    monkeypatch.setenv("FAKE_TAU_HANGS_ON", "99")
    await step.execute("c2", args)
    first, second, third = _runs(fake_tau)
    note = second["stdin"]
    assert "killed at its 3s wall before it reported" not in first["stdin"]
    assert "The last sub-agent on this task was killed at its 3s wall before it reported" in note
    assert "Its last reasoning, the end of it:\n[...] xxx" in note
    assert note.count("x") < 2100 and "so case 3 encodes as (1, 0)" in note
    assert "Uncommitted in its scope: tests/test_x.py" in note
    # Taken once: the step's second attempt has the first's report instead.
    assert "so case 3 encodes" not in third["stdin"]
    assert _loaded_module()._KILLED_PROGRESS == {}


@pytest.mark.anyio
async def test_wall_kill_step_result_shows_the_killed_workers_last_words(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # q35 R51: W5 said "test is buggy, cannot make both pass" and was killed at its
    # step budget; the result said its words went to the next brief, and the driver
    # spent a 3.6-min turn finding the bug again.
    project = _git_project(tmp_path, monkeypatch)
    monkeypatch.chdir(project)
    monkeypatch.setenv("FAKE_TAU_SUCCEEDS_ON", "99")
    monkeypatch.setenv("FAKE_TAU_HANGS_ON", "1")
    monkeypatch.setenv("FAKE_TAU_MIDTURN", "x" * 5000 + " test is buggy, cannot make both pass")
    monkeypatch.setenv("FAKE_TAU_WRITES", json.dumps({"tests/test_x.py": "def test_x(): ...\n"}))
    _ready_task(fake_beagle)
    runtime, _ = _bound(tmp_path)
    args = {
        "task": "T0002",
        "criteria": "c",
        "done_when": "grep -q done done.txt",
        "scope": ["done.txt", "tests/test_x.py"],
        "timeout": 3,
    }

    killed = (await _tool(runtime, "pursuit_step").execute("c1", args)).text

    said = "What it said last (its reasoning, the end of it):\n[...] xxx"
    assert said in killed and "test is buggy, cannot make both pass" in killed
    # Short in the driver's context; the next brief keeps the longer tail.
    assert "x" * 500 in killed and "x" * 600 not in killed
    assert killed.index(said) < killed.index("In the tree now:\n") < killed.index("test_x.py")
    assert "test is buggy" in _loaded_module()._KILLED_PROGRESS[(str(project.resolve()), "T0002")]


@pytest.mark.anyio
async def test_new_route_carries_killed_progress_to_the_sibling(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # q35 R51: W5's last words were kept for T0003's next brief; the driver took a
    # new route, T0007, and W6's brief had no word of them.
    project = _git_project(tmp_path, monkeypatch)
    monkeypatch.chdir(project)
    _failing_open_task(fake_beagle, monkeypatch)
