    notes = {}
    for name, fill, length_stops, refusals in (
        ("call", "call", "2", "0"),
        ("refused call", "", "0", "2"),
        ("call and text", "text", "1", "1"),
        ("text", "text", "2", "0"),
        ("thinking", "", "2", "0"),
    ):
        monkeypatch.setenv("FAKE_TAU_CUT_FILL", fill)
        monkeypatch.setenv("FAKE_TAU_LENGTH_STOPS", length_stops)
