def test_truncated_call_names_char_budget() -> None:
    # R27: "parts of a few hundred lines" let W2 resend 10k characters of hex four times.
    raw = '{"path":"tests/cases.json","content":"' + "0a1b" * 2500

    refusal = _module()._truncated_call({"_raw_arguments": raw})

    assert refusal is not None
    assert f"cut off after {len(raw)} characters" in refusal
    assert f"parts of at most {len(raw) // 2} characters" in refusal
    assert "lines" not in refusal
    assert "short script run inline by bash" in refusal
    assert "cut off again" not in refusal


def test_cutoff_advice_sizes_parts_to_output_limit(monkeypatch: pytest.MonkeyPatch) -> None:
    # R33: told "parts of at most 13644 characters", W2 sent ~28k characters again.
    raw = '{"path":"tests/cases.json","content":"' + "0a1b" * 7000

    refusal = _module()._truncated_call({"_raw_arguments": raw})
    monkeypatch.setenv(_module().WORKER_OUTPUT_TOKENS_ENV, "4096")
    smaller = _module()._truncated_call({"_raw_arguments": raw})

    assert refusal is not None and smaller is not None
    assert "parts of at most 8192 characters, one write per part, appending" in refusal
    assert "parts of at most 4096 characters" in smaller


@pytest.mark.anyio
async def test_worker_guard_refuses_reads_past_half_cap_with_nothing_written(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R33: W3 and W7 re-read references until the cap, writing at the last call.
    monkeypatch.setenv(_module().WORKER_MAX_TURNS_ENV, "10")
    runtime = _scoped_worker(tmp_path, monkeypatch, scope="tests/x.py")
    read = _tool_with_hooks(runtime, "read")
    write = _tool_with_hooks(runtime, "write")

    early = [await read.execute(f"r{i}", {"path": "ref.txt"}) for i in range(5)]
    late = await read.execute("r5", {"path": "ref.txt"})
    own = await read.execute("r6", {"path": "tests/x.py"})
    wrote = await write.execute("w1", {"path": "tests/x.py", "content": "x"})
    after = await read.execute("r7", {"path": "ref.txt"})

    assert all(result.text == "ran" for result in early)
    assert late.text != "ran"
    assert "5 of 10 calls used and nothing written" in late.text
    assert "Write tests/x.py now; re-read only what a write needs." in late.text
    assert own.text == "ran" and wrote.text == "ran" and after.text == "ran"


@pytest.mark.anyio
async def test_no_write_guard_counts_in_scope_paging(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R34: W9 paged the in-scope tests/cases.json 27 times and wrote nothing.
    monkeypatch.setenv(_module().WORKER_MAX_TURNS_ENV, "20")
    runtime = _scoped_worker(tmp_path, monkeypatch, scope="tests/")
    window = _module().WINDOW_LINES
    project = tmp_path / "project"
    (project / "tests").mkdir()
    (project / "tests" / "cases.json").write_text("1\n" * (window * 3 - 5))
    (project / "tests" / "small.py").write_text("x = 1\n")
    read = _tool_with_hooks(runtime, "read")
    write = _tool_with_hooks(runtime, "write")

    pages = [
        await read.execute(f"r{i}", {"path": "tests/cases.json", "offset": 1 + window * (i % 3)})
        for i in range(10)
    ]
    small = await read.execute("s1", {"path": "tests/small.py"})
    again = await read.execute("s2", {"path": "tests/small.py"})
    wrote = await write.execute("w1", {"path": "tests/x.py", "content": "x"})
    after = await read.execute("r10", {"path": "tests/cases.json"})

    # Calls 1-10 are within half the cap of 20, so all ten pages pass.
    assert all(page.text == "ran" for page in pages)
    # Call 11 is past half: tests/small.py's first read fits one pass; its second does not.
    assert small.text == "ran"
    assert again.text != "ran"
    assert "this is read 2 of a 1-line file that one pass reads in 1" in again.text
    assert "11 of 20 calls are used with nothing written" in again.text
    assert "`python3 -c` over the file" in again.text and "write tests/ now" in again.text
    assert wrote.text == "ran" and after.text == "ran"

    refusal = _module()._reread_refusal(
        "read", {"path": "tests/cases.json"}, project, ("tests/",), 11, {}
    )
    assert refusal is None
    counted = {(project / "tests" / "cases.json").resolve(): 3}
    paged = _module()._reread_refusal(
        "read", {"path": "tests/cases.json"}, project, ("tests/",), 11, counted
    )
    assert paged is not None
    assert f"read 4 of a {window * 3 - 5}-line file that one pass reads in 3" in paged

    # R34 W9: a 4048-line file takes 68 reads, more than a cap of 20 allows; it is
    # refused after a quarter of the cap.
    (project / "tests" / "cases.json").write_text("1\n" * 4048)
    cases = (project / "tests" / "cases.json").resolve()
    within = _module()._reread_refusal(
        "read", {"path": "tests/cases.json"}, project, ("tests/",), 11, {cases: 4}
    )
    assert within is None
    long = _module()._reread_refusal(
        "read", {"path": "tests/cases.json"}, project, ("tests/",), 11, {cases: 5}
    )
    assert long is not None
    assert "read 6 of a 4048-line file that takes 68 reads at 60 lines per read" in long
    assert "more than the 5 a file gets under a cap of 20" in long


@pytest.mark.anyio
async def test_reread_refusal_on_reference_offers_search(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R40: a refused reference re-read said only "write now"; drivers fell back on grep.
    module = _module()
    monkeypatch.setenv(module.WORKER_MAX_TURNS_ENV, "10")
    real = shutil.which
    monkeypatch.setattr(
        module.shutil, "which", lambda name, *a, **k: None if name == "tilth" else real(name)
    )
    runtime = _scoped_worker(tmp_path, monkeypatch, scope="tests/x.py")
    project = tmp_path / "project"
    (project / "references").mkdir()
    (project / "references" / "paper.txt").write_text("the value is 42\n")
    (project / "notes.txt").write_text("x\n")
    read = _tool_with_hooks(runtime, "read")

    early = [await read.execute(f"r{i}", {"path": "references/paper.txt"}) for i in range(5)]
    late = await read.execute("r5", {"path": "references/paper.txt"})
    other = module._reread_refusal("read", {"path": "notes.txt"}, project, ("tests/x.py",), 6)

    assert all(result.text == "ran" for result in early)
    assert "refusing to read references/paper.txt: 5 of 10 calls used" in late.text
    grep = 'grep -n -i -F "<words>" references/*.txt'
    assert f"Search the references instead with bash, `{grep}`, for the line" in late.text
    assert "then write tests/x.py now." in late.text
    assert other is not None and "Search the references" not in other

    monkeypatch.setattr(
        module.shutil, "which", lambda name, *a, **k: "/bin/tilth" if name == "tilth" else None
    )
    refusal = module._reread_refusal(
        "read", {"path": "references/paper.txt"}, project, ("tests/x.py",), 6
    )
    assert refusal is not None
    assert '`tilth "<words>" --scope references`' in refusal


def _reference_worker(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, cap: int, scope: str = "tests/"
) -> tuple[ExtensionRuntime, Path]:
    """A worker on T0003 with `scope`, a bound check and a 300-line reference."""
    monkeypatch.setenv(_module().WORKER_MAX_TURNS_ENV, str(cap))
    runtime = _scoped_worker(tmp_path, monkeypatch, scope=scope)
    project = tmp_path / "project"
    (project / ".beagle" / "tree").mkdir(parents=True, exist_ok=True)
    (project / ".beagle" / "tree" / "T0003.md").write_text(
        '+++\nid = "T0003"\ndone_when = "python3 -m pytest -q tests/"\n+++\n'
    )
    (project / "references").mkdir()
    (project / "references" / "paper.txt").write_text(
        "".join(f"line {n}: the value is {n}\n" for n in range(1, 301))
    )
    (project / "notes.txt").write_text("x\n")
    return runtime, project


@pytest.mark.anyio
async def test_known_answers_worker_ranged_reference_read_is_not_refused(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # q35 R51: W1 and W3 were refused first-time 20-120-line reads of the references
    # at 15-18 of 30 calls, and W2 and W3 the greps that refusal offered.
    runtime, _ = _reference_worker(tmp_path, monkeypatch, cap=10)
    read = _tool_with_hooks(runtime, "read")
    bash = _tool_with_hooks(runtime, "bash")
    paper = "references/paper.txt"

    windows = [
        await read.execute(f"r{i}", {"path": paper, "offset": 1 + 30 * i, "limit": 30})
        for i in range(10)
    ]
    searches = [
        await bash.execute("g1", {"command": 'grep -n -i -F "value is 7" references/*.txt'}),
        await bash.execute("g2", {"command": f"sed -n '290,300p' {paper}"}),
        await bash.execute("g3", {"command": 'tilth "value" --scope references | head -5'}),
    ]
    # None of the 13 counted, so calls 14-18 are the first five of the cap of 10.
    others = [await read.execute(f"n{i}", {"path": "notes.txt"}) for i in range(5)]
    late = await read.execute("n5", {"path": "notes.txt"})
    whole = await read.execute("p1", {"path": paper})
    wide = await read.execute("p2", {"path": paper, "offset": 1, "limit": 120})

    assert all(result.text == "ran" for result in windows + searches + others)
    assert "refusing to read notes.txt: 5 of 10 calls used and nothing written" in late.text
    # A read of the whole reference, or of more than one window, counts as before.
    assert "refusing to read references/paper.txt: 6 of 10" in whole.text
    assert "refusing to read references/paper.txt: 7 of 10" in wide.text


@pytest.mark.anyio
async def test_nth_reread_of_a_reference_window_is_still_refused(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R34/R40: 9B workers re-read the same reference windows until the cap.
    runtime, _ = _reference_worker(tmp_path, monkeypatch, cap=10)
    read = _tool_with_hooks(runtime, "read")
    window = {"path": "references/paper.txt", "offset": 41, "limit": 20}

    first = await read.execute("r0", window)
    rereads = [await read.execute(f"r{i}", window) for i in range(1, 6)]
    again = await read.execute("r6", window)
    other = await read.execute("r7", {**window, "offset": 61})

    assert first.text == "ran" and all(result.text == "ran" for result in rereads)
    assert "refusing to read references/paper.txt: 5 of 10 calls used" in again.text
    assert "Search the references instead with bash" in again.text
    assert other.text == "ran"


@pytest.mark.anyio
async def test_reference_search_offered_by_a_read_refusal_is_not_refused(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # q35 R51: refused a read, W2 ran the grep the refusal offered and was refused
    # it four times at 22-25 of 30 calls, then wrote its sources from memory.
    module = _module()
    real = shutil.which
    monkeypatch.setattr(
        module.shutil, "which", lambda name, *a, **k: None if name == "tilth" else real(name)
    )
    runtime, project = _reference_worker(tmp_path, monkeypatch, cap=8, scope="tests/x.py")
    read = _tool_with_hooks(runtime, "read")
    bash = _tool_with_hooks(runtime, "bash")

    reads = [await read.execute(f"r{i}", {"path": "references/paper.txt"}) for i in range(5)]
    runs = [await bash.execute(f"b{i}", {"command": "python3 -c 'print(1)'"}) for i in range(2)]
    offered = 'grep -n -i -F "<words>" references/*.txt'
    searches = [
        await bash.execute("g1", {"command": offered.replace("<words>", "value is 7")}),
        await bash.execute("g2", {"command": "grep -n 'grow(1' references/paper.txt | head"}),
        await bash.execute("g3", {"command": "sed -n '1,20p' references/paper.txt 2>&1"}),
    ]
    elsewhere = await bash.execute("g4", {"command": "grep -rn value ."})

    assert [result.text == "ran" for result in reads] == [True] * 4 + [False]
    assert f"Search the references instead with bash, `{offered}`" in reads[-1].text
    assert runs[0].text == "ran" and "6 of 8 calls used and nothing written" in runs[1].text
    assert all(result.text == "ran" for result in searches)
    assert "refusing to run this command" in elsewhere.text

    search = module._reference_search_call
    for command in (
        'tilth "seed stamp" --scope references',
        "grep -c x references/paper.txt && grep -n y references/",
        "rg -n -e norm references/paper.txt | sort | uniq",
    ):
        assert search(command, project, project), command
    for command in (
        "grep -n x references/paper.txt > tests/cases.json",
        "grep -n x references/paper.txt notes.txt",
        "grep -n x references/paper.txt | python3 -c 'print(1)'",
        "sed -i 's/a/b/' references/paper.txt",
        "sed -n '1,5w out.txt' references/paper.txt",
        'tilth "value"',
        "cat references/paper.txt",
    ):
        assert not search(command, project, project), command


@pytest.mark.anyio
async def test_no_write_guard_counts_bash_runs_without_writes(
    tmp_path: Path, beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R34: W7's encoder trials and W8's analysis scripts wrote nothing, never refused.
    monkeypatch.setenv(_module().WORKER_MAX_TURNS_ENV, "8")
    runtime = _scoped_worker(tmp_path, monkeypatch, scope="tests/x.py")
    project = tmp_path / "project"
    (project / ".beagle" / "tree").mkdir(parents=True, exist_ok=True)
    (project / ".beagle" / "tree" / "T0003.md").write_text(
        '+++\nid = "T0003"\ndone_when = "python3 -m pytest -q tests/x.py"\n+++\n'
    )
    bash = _tool_with_hooks(runtime, "bash")
    write = _tool_with_hooks(runtime, "write")

    early = [await bash.execute(f"b{i}", {"command": "python3 -c 'print(1)'"}) for i in range(6)]
    trial = await bash.execute("b6", {"command": "python3 -c 'print(2)' > /tmp/out.txt"})
    check = await bash.execute("b7", {"command": "python3  -m pytest -q tests/x.py 2>&1 | tail"})
    scripted = await bash.execute("b8", {"command": "printf x > tests/x.py"})
    after = await bash.execute("b9", {"command": "python3 -c 'print(3)'"})
    wrote = await write.execute("w1", {"path": "tests/x.py", "content": "x"})

    # Calls 1-6 are within three-quarters of the cap of 8.
    assert all(result.text == "ran" for result in early)
    assert trial.text != "ran"
    assert "6 of 8 calls used and nothing written" in trial.text
    assert "Write tests/x.py now with `write` or `edit`" in trial.text
    assert "run the check: python3 -m pytest -q tests/x.py" in trial.text
    assert check.text == "ran"
    assert scripted.text == "ran"
    assert after.text == "ran" and wrote.text == "ran"


