@pytest.mark.anyio
async def test_unproven_refusal_first_line_is_a_complete_call_within_the_quote(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # Audit 11: three branches put prose ("a done_when running the data file's
    # test") where the values go, and the first line was not bounded to the quote.
    project = _pursuit_project(tmp_path)
    monkeypatch.chdir(project)
    _open_on_done_txt(project, fake_beagle, ["done.txt"])
    _r21_tree(project)
    (project / "clock.py").write_text("def tick(n):\n    return n + 1\n")
    (project / "tests" / "test_clock.py").write_text(
        "from clock import tick\n\n\ndef test_tick():\n    assert tick(1) == 2\n"
    )
    runtime, _ = _bound(tmp_path)
    module = _loaded_module()
    pytest_clock = "python3 -m pytest -q tests/test_clock.py"
    branches = [
        # The check's test reads a data file outside the scope.
        (["tests/test_case_data.py"], R21_CHECK, R21_CHECK, ["tests/cases.json"]),
        # The scope holds the data file and its test.
        (
            ["tests/cases.json", "tests/test_case_data.py"],
            "grep -q in tests/cases.json",
            R21_CHECK,
            [],
        ),
        # Tests only: the module the test imports joins the scope.
        (["tests/test_clock.py"], pytest_clock, pytest_clock, ["clock.py"]),
        # Code: the test that imports it is run.
        (["clock.py"], "grep -q tick clock.py", pytest_clock, ["tests/test_clock.py"]),
    ]
    for scope, check, done_when, added in branches:
        record = {"id": "T0002", "title": "Parser", "status": "open"}
        (fake_beagle / "show.out").write_text(
            json.dumps(record | {"done_when": check, "scope": scope})
        )
        module._NOT_DONE.clear()
        module._UNPROVEN.add((str(Path.cwd()), "T0002"))

        result = await _tool(runtime, "pursuit_step").execute("c1", {"task": "T0002"})

        first = result.text.splitlines()[0]
        assert first.startswith(
            'pursuit_step: T0002 not run — call instead: pursuit_step task="T0002", '
            f"new_route=true, done_when={json.dumps(done_when)}, "
            f"scope={json.dumps([*scope, *added])}, notes="
        ), first
        assert len(first) <= module.ESCALATION_HEAD_CHARS, first
        for prose in ("a done_when", "running", "naming", "<"):
            assert prose not in first, first
    assert _runs(fake_tau) == []


@pytest.mark.anyio
async def test_spawn_refusal_does_not_offer_new_route_and_forbid_it(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # q35 10-11, 11:19:02: T0010's unproven refusal said "call instead: ...
    # new_route=true" on its first line and "leave done_when and new_route out"
    # below it; at 11:19:17 that new route, keeping the bound check and scope,
    # was refused as changing nothing.
    project = _pursuit_project(tmp_path)
    monkeypatch.chdir(project)
    _open_on_done_txt(project, fake_beagle, ["done.txt"])
    _r21_tree(project)
    runtime, _ = _bound(tmp_path)
    module = _loaded_module()
    step = _tool(runtime, "pursuit_step")
    key = (str(Path.cwd()), "T0002")
    scope = ["tests/cases.json", "tests/test_case_data.py"]
    said = []
    for bound in ("grep -q in tests/cases.json", R21_CHECK):
        record = {"id": "T0002", "title": "Parser", "status": "open"}
        (fake_beagle / "show.out").write_text(
            json.dumps(record | {"done_when": bound, "scope": scope})
        )
        module._UNPROVEN.add(key)
        module._NOT_DONE[key] = module.ESCALATE_AFTER
        module._NOT_DONE_DEMAND[key] = "no defect could be put back into a file in its scope"
        module._LAST_CHECK_EXIT[key] = 0
        rerun = {"task": "T0002", "notes": module._NOT_DONE_DEMAND[key]}
        said.append((await step.execute("c1", rerun)).text)
    rebound, kept = said

    for text in said:
        assert not ("new_route=true" in text and "new_route out" in text), text
    # A route with a new check is still offered, and nothing forbids it.
    assert 'pursuit_step task="T0002", new_route=true' in rebound.splitlines()[0]
    # The only route left keeps the bound check and scope: it is not offered.
    assert "new_route=true" not in kept
    assert "The only new route left keeps both" in kept
    assert kept.splitlines()[0].endswith(
        "call instead: " + module._split_call("T0002", {"scope": scope})
    )
    assert module.STOP_OPTION in kept
    offered = {"task": "T0002", "new_route": True, "done_when": R21_CHECK, "scope": scope}
    sent = await step.execute("c2", offered | {"notes": "New route: the data's absence"})
    assert "No new route for T0002" in sent.text
    assert _runs(fake_tau) == []


