def test_infeasible_offer_warns_it_would_seal_the_parent(tmp_path: Path) -> None:
    # q35 10-11: the hints offered T0011's infeasible close as a normal exit, then a
    # re-plan of T0002; the close sealed T0002, and nothing had said it would.
    module = _module()

    offer = module._spawn_limit_offer("T0011", "grep -q done done.txt", ["done.txt"], _r26_chain())
    spent = module._source_judge_spent(
        "T0004", 5, "tests/cases.json", "case seed", "", "pursuit_step: T0004 not run — ", tmp_path
    )

    close = 'Close it infeasible instead: pursuit_step task="T0011", abandon="infeasible: '
    assert close in offer
    warning = offer.partition(close)[2].partition(". ")[2]
    assert warning.startswith(
        "That close seals T0002: T0011 would end undone with no task holding its work"
    )
    assert "T0002 could never be all-done" in warning
    assert "only the owner could then re-scope or abandon T0002" in warning
    assert "stop instead, and ask the user" in warning
    assert "pursuit_plan task=" not in offer
    assert 'pursuit_step task="T0004", abandon="infeasible: ' in spent
    assert "That close seals its parent: T0004 would end undone" in spent


@pytest.mark.anyio
async def test_infeasible_abandon_refused_below_the_limit(
    tmp_path: Path, beagle: Path, fake_beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # Audit 12: abandon="infeasible: …" closed any task, pending included, so a
    # hard task had an easy way out before its routes were tried.
    monkeypatch.chdir(_pursuit_project(tmp_path))
    (fake_beagle / "next.out").write_text(json.dumps({"open": [{"id": "T0011"}], "ready": []}))
    (fake_beagle / "close.out").write_text("T0011 infeasible\n")
    runtime, _ = _bound(tmp_path)
    step = _tool(runtime, "pursuit_step")
    why = {"task": "T0011", "abandon": "infeasible: the check cannot be shown to refuse"}

    (fake_beagle / "tree.out").write_text(json.dumps({"nodes": _r26_chain("pending")}))
    pending = await step.execute("c1", why)
    below = [n for n in _r26_chain() if n["id"] != "T0009"]
    (fake_beagle / "tree.out").write_text(json.dumps({"nodes": below}))
    short = await step.execute("c2", why)

    assert _pursuit_calls(fake_beagle, "close") == []
    assert "T0011 not closed infeasible — it is pending" in pending.text
    assert 'Open it first with pursuit_step task="T0011" and a done_when' in pending.text
    assert "not closed infeasible — its retry chain (T0009, T0010, T0011) holds 3" in short.text
    assert "and beagle refuses a new route only once a chain holds more than 3" in short.text
    assert 'pursuit_step task="T0011", new_route=true' in short.text
    assert 'pursuit_step task="T0011" with notes' in short.text


def test_attempt_limit_arithmetic_reads_true(tmp_path: Path) -> None:
    # q35 10-11, 11:50:35: "holds 3 attempt(s), below beagle's limit of 3". beagle
    # spawns while a chain holds 3 and refuses once it holds more (`_at_spawn_limit`).
    module = _module()
    assert module.SPAWN_LIMIT == 3
    for n in range(1, 6):
        chain = [f"T00{20 + i}" for i in range(n)]
        nodes = [
            {"id": "T0001", "parent": "", "status": "open", "container": True},
            {"id": "T0002", "parent": "T0001", "status": "open", "container": True},
        ] + [
            {
                "id": t,
                "parent": "T0002",
                "status": "superseded" if t != chain[-1] else "open",
                "sibling_of": chain[i - 1] if i else "",
            }
            for i, t in enumerate(chain)
        ]
        task = chain[-1]
        limited = module._at_spawn_limit(task, nodes)
        assert limited == (n > 3)
        said = (
            module._spawn_limit_offer(task, "false", ["done.txt"], nodes)
            if limited
            else module._close_infeasible(task, "why", nodes, ["T0001"], tmp_path, tmp_path)
        )
        attempts = f"{n} attempt" + ("" if n == 1 else "s")
        assert f"retry chain ({', '.join(chain)}) holds {attempts}" in said, said
        assert "below beagle's limit" not in said
        assert ("past beagle's limit of 3" in said) == limited, said
        assert ("only once a chain holds more than 3" in said) == (not limited), said


