def test_known_answers_fix_recognised_by_scope(tmp_path: Path) -> None:
    # R34 #27: T0007, made as the fix, was refused as locked for its title's words.
    project = _pursuit_project(tmp_path)
    goal = _locked_cases_test(project)
    module = _module()
    title = "Fix test cases in the data file"
    assert module._fixes_known_answers(title) is False

    assert module._fixes_known_answers_in(title, ["tests/test_cases.py"], goal) is True
    assert module._fixes_known_answers_in(title, ["./tests/test_cases.py"], goal) is True
    assert module._locked_scope_problem(["tests/test_cases.py"], project, title, "T0007") is None
    # Other work beside the locked file is no fix, and an empty scope is none either.
    mixed = ["parser.py", "tests/test_cases.py"]
    assert module._fixes_known_answers_in(title, mixed, goal) is False
    assert module._fixes_known_answers_in(title, ["tests/"], goal) is False
    assert module._fixes_known_answers_in(title, [], goal) is False
    assert module._locked_scope_problem(
        ["parser.py", "tests/test_cases.py"], project, title, "T0007"
    )


def test_missing_pytest_node_in_unwritable_file_refused(tmp_path: Path) -> None:
    # R34 #19: the check named a test the locked file did not hold; it exited 4.
    project = _pursuit_project(tmp_path)
    _locked_cases_test(project)
    (project / "tests" / "test_other.py").write_text(
        "def test_one():\n    pass\n\n\nclass TestTwo:\n    def test_it(self):\n        pass\n"
    )
    guard = _module()._pytest_node_missing_problem
    missing = "tests/test_cases.py::test_encode_decode_roundtrip"

    said = guard(f"python3 -m pytest -q {missing}", ["parser.py"], project)
    assert said is not None
    assert "`test_encode_decode_roundtrip`, which is not in tests/test_cases.py" in said
    assert "its tests are: test_cases" in said and "it is locked" in said
    outside = guard("pytest -q tests/test_other.py::test_three", ["parser.py"], project)
    assert outside is not None and "its tests are: test_one, TestTwo" in outside
    assert "outside the task's scope" in outside
    # Locked even under a directory scope.
    assert guard(f"pytest -q {missing}", ["parser.py", "tests/"], project) is not None

    for check, scope in (
        ("pytest -q tests/test_other.py::test_three", ["parser.py", "tests/test_other.py"]),
        ("pytest -q tests/test_other.py::test_three", ["tests/"]),
        ("pytest -q tests/test_other.py::TestTwo::test_it", ["parser.py"]),
        ("pytest -q tests/test_other.py::test_one[1]", ["parser.py"]),
        ("pytest -q tests/test_cases.py::test_cases", ["parser.py"]),
        ("pytest -q tests/test_cases.py", ["parser.py"]),
        ("pytest -q tests/test_new.py::test_x", ["parser.py"]),
    ):
        assert guard(check, scope, project) is None, check


#: R34's reference table, two rows: each input line, then the line giving its result.
R34_REFERENCE = (
    "Example | Unencoded data (hex)\n"
    "| Data bytes | Encoded with COBS (hex)\n"
    "\n"
    "3 | 00 11 00\n"
    "| 3 | 01 02 11 01 00\n"
    "\n"
    "4 | 11 22 00 33\n"
    "| 4 | 03 11 22 02 33 00\n"
    "\n"
    "7 | 01 02 03 ... FD FE\n"
    "| 254 | FF 01 02 03 ... FD FE 00\n"
)


@pytest.mark.anyio
async def test_known_answer_source_must_hold_expected_result(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # R34: single_zero_byte's source was its input line, "1 | 00", and its expected
    # [1, 0] was wrong; the reference's next line gives 01 01 00.
    module = _module()
    reference = [module._normalised(line) for line in R34_REFERENCE.splitlines() if line.strip()]
    right = [3, 17, 34, 2, 51, 0]
    long = [255, *range(1, 255), 0]
    held = {
        "next-line": {"in": [17, 34, 0, 51], "expected": right, "source": "4 | 11 22 00 33"},
        "result-line": {"in": [1], "expected": right, "source": "| 4 | 03 11 22 02 33 00"},
        "0x": {"in": [1], "expected": right, "source": "0x03, 0x11, 0x22, 0x02, 0x33, 0x00"},
        "escaped": {"in": [1], "expected": right, "source": r"\x03\x11\x22\x02\x33\x00"},
        "bare-hex": {"in": [1], "expected": right, "source": "031122023300"},
        "decimal": {"in": [1], "expected": right, "source": "gives [3, 17, 34, 2, 51, 0]"},
        "elided": {"in": [1], "expected": long, "source": "7 | 01 02 03 ... FD FE"},
        "string": {"in": "a", "output": "(1, (0, 1))", "source": "is (1, (0, 1)) here"},
        "hex-string": {"in": "a", "result": "03 11 22", "source": "0x03 0x11 0x22"},
        "bool": {"in": [0], "expected": True, "source": "prose without values"},
        "short": {"in": [0], "expected": 7, "source": "prose without values"},
        "as-input": {"in": [0, 17, 0], "decoded": [0, 17, 0], "source": "3 | 00 11 00"},
    }
    for name, case in held.items():
        assert not module._result_unquoted(case, [reference]), name
    wrong = {
        "input-line": {"in": [0, 17, 0], "expected": [1, 17, 0], "source": "3 | 00 11 00"},
        "slice": {"in": [0, 17, 0], "expected": [1, 0], "source": "| 3 | 01 02 11 01 00"},
        "prose": {"in": [42], "expected_encoded": [1, 42, 0], "source": "Bold is data."},
        "elided-wrong": {"in": [1], "expected": long[:-1], "source": "7 | 01 02 03 ... FD FE"},
        "number": {"in": [0], "expected": 1234, "source": "prose without values"},
        "string": {"in": "a", "output": "(1, (0, 1))", "source": "is (1, (1, 0)) here"},
    }
    for name, case in wrong.items():
        assert module._result_unquoted(case, [reference]), name

    cases = [
        {"name": "zero_with_data", "in": [0, 17, 0], "out": [1, 17, 0]},
        {"name": "data_with_zero", "in": [17, 34, 0, 51], "out": right},
        {"name": "flag", "in": [0], "out": True},
    ]
    for case, source in zip(cases, ["3 | 00 11 00", *2 * ["4 | 11 22 00 33"]], strict=True):
        case["source"] = source
    project = _cases_task(tmp_path, fake_beagle, monkeypatch, CASES_DATA_TEST)
    (project / "references").mkdir()
    (project / "references" / "cobs.txt").write_text(R34_REFERENCE)
    writes = json.loads(os.environ["FAKE_TAU_WRITES"])
    writes["tests/cases.json"] = json.dumps(cases)
    monkeypatch.setenv("FAKE_TAU_WRITES", json.dumps(writes))

    result = await _step_cases(tmp_path, locks=CASES_SCOPE)

    assert "stays open" in result.text and "nothing is locked" in result.text
    assert "1 of 3 cases in tests/cases.json have a source that does not give" in result.text
    assert (
        "case zero_with_data's source quotes its input or prose, not its expected result: "
        "quote the line that gives the result" in result.text
    )
    assert not (project / ".beagle" / "locked").exists()
    assert _pursuit_calls(fake_beagle, "close") == []
    found = module._unquoted_cases(project, ["tests/cases.json"])
    assert found is not None
    assert found[:5] == ("tests/cases.json", 1, 3, ["zero_with_data"], True)
    cases[0]["out"] = [1, 2, 17, 1, 0]
    (project / "tests" / "cases.json").write_text(json.dumps(cases))
    assert module._unquoted_cases(project, ["tests/cases.json"]) is None


def test_source_judge_judges_results_under_encoded_and_decoded_keys(tmp_path: Path) -> None:
    # q35 R56: 11 cases keyed input_hex/encoded_hex/decoded_hex all quoted one prose
    # sentence, example 11's encoding was wrong, and the judge found no result to
    # judge in any of them, so the close passed with no hold.
    module = _module()
    prose = "These examples show how various data sequences would be encoded by the COBS algorithm."
    (tmp_path / "references").mkdir()
    (tmp_path / "references" / "cobs.txt").write_text(f"{prose}\n\n{R34_REFERENCE}")
    (tmp_path / "tests").mkdir()
    data = tmp_path / "tests" / "cases.json"
    # example_3's decoded_hex echoes its input_hex, on the input row it quotes.
    rows = {
        "example_3": "3 | 00 11 00",
        "example_4": ["4 | 11 22 00 33", "| 4 | 03 11 22 02 33 00"],
    }
    cases = [
        {
            "name": "example_3",
            "input_hex": "00 11 00",
            "encoded_hex": "01 02 11 01 00",
            "decoded_hex": "00 11 00",
            "source": prose,
        },
        {
            "name": "example_4",
            "input_hex": "11 22 00 33",
            "encoded_hex": "03 11 22 02 33 00",
            "decoded_hex": "11 22 00 33",
            "source": prose,
        },
    ]
    data.write_text(json.dumps(cases))

    found = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert found is not None
    assert found[:5] == ("tests/cases.json", 2, 2, ["example_3", "example_4"], True)

    for case in cases:
        case["source"] = rows[case["name"]]
    data.write_text(json.dumps(cases))
    assert module._unquoted_cases(tmp_path, ["tests/cases.json"]) is None

    cases[1]["encoded_hex"] = "03 11 22 33 00"
    data.write_text(json.dumps(cases))
    found = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert found is not None
    assert found[:5] == ("tests/cases.json", 1, 2, ["example_4"], True)


#: A reference defining an operation by rules, with only a few worked results (R40).
RULES_REFERENCE = (
    "The twist of a pair swaps its halves and adds one to the first.\n"
    "twist((a, b)) = (b + 1, a), where a and b are any values\n"
    "\n"
    "For example, a twist of the unit pair gives:\n"
    "(2, 1)\n"
    "twist((1, 2)) = (3, 1)\n"
    "twist((0, 5)) → (6, 0)\n"
    "twist((7, 7)) ∼ (8, 7)\n"
    "twist((4, 4)) = (5, 4)\n"
    "twist((x, y)) is not defined for a nested pair\n"
    "12\n"
)


async def _unsourced_result_step(
    tmp_path: Path, fake_beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> tuple[Any, Path]:
    """A close whose cases quote the reference's rule prose, for results it never gives."""
    cases = [
        {
            "name": "nested_twist",
            "in": [1, 2, 3, 4],
            "out": [9, 1, 3, 9],
            "source": "The twist of a pair swaps its halves and adds one to the first.",
        },
        {
            "name": "unit_twist",
            "in": [1, 2],
            "out": [3, 1],
            "source": "twist((1, 2)) = (3, 1)",
        },
    ]
    project = _cases_task(tmp_path, fake_beagle, monkeypatch, CASES_DATA_TEST)
    (project / "references").mkdir()
    (project / "references" / "rules.txt").write_text(RULES_REFERENCE)
    writes = json.loads(os.environ["FAKE_TAU_WRITES"])
    writes["tests/cases.json"] = json.dumps(cases)
    monkeypatch.setenv("FAKE_TAU_WRITES", json.dumps(writes))
    return await _step_cases(tmp_path, locks=CASES_SCOPE), project


