@pytest.mark.anyio
async def test_judge_only_escalation_stops_offering_reruns_after_cap(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # R40 follow-up: unlimited notes-only reruns would be the loop the split was;
    # after SOURCE_JUDGE_RERUNS, the escalation offers the close or a stop.
    module, project, record = await _source_judge_escalated(tmp_path, fake_beagle, monkeypatch)
    key = (str(project), "T0002")
    assert module.SOURCE_JUDGE_RERUNS == 3
    cap = module.JUDGE_NOTES_UNTIL + module.SOURCE_JUDGE_RERUNS
    taken = {"task": "T0002", "notes": "replace the case"}
    module._NOT_DONE[key] = cap - 1
    assert module._judge_notes_rerun("T0002", taken, record, project)

    module._NOT_DONE[key] = cap
    refused = module._escalation("T0002", cap, taken, record, project, False, False)
    unchanged = module._unchanged_route_escalation("T0002", cap, record, "No new route.", project)
    still = module._still_open_escalation("T0002", cap, project)

    assert not module._judge_notes_rerun("T0002", taken, record, project)
    why = "no line of references/*.txt gives the result of case nested_twist in tests/cases.json"
    close = f'pursuit_step task="T0002", abandon="infeasible: {why}"'
    assert _quoted_head(refused) == f"pursuit_step: T0002 not run — call instead: {close}"
    assert _quoted_head(still) == f"T0002 is still open — call instead: {close}"
    said = (
        "The cases the references do not answer, case nested_twist in tests/cases.json, "
        "cannot close T0002"
    )
    for text in (refused, unchanged, still):
        assert said in text
        assert f"- {close}, closing it infeasible on those cases;" in text
        assert "- stop, and tell the user what blocks it." in text
        assert "pursuit_plan" not in text and "notes=" not in text
        assert "new_route=true" not in text
    # The offered close is taken below beagle's spawn limit.
    (fake_beagle / "close.out").write_text("T0002 infeasible\n")
    nodes = [{"id": "T0001"}, {"id": "T0002", "parent": "T0001", "status": "open"}]
    closed = module._close_infeasible("T0002", why, nodes, ["T0001"], project, project / "goal")
    assert "not closed infeasible" not in closed
    assert len(_pursuit_calls(fake_beagle, "close")) == 1


#: R35's references/Consistent_Overhead_Byte_Stuffing.txt, lines 31-33, 45-47 and 66-88.
R35_REFERENCE = (
    "COBS transforms an arbitrary string of bytes in the range [0,255] into bytes in the "
    "range [1,255]. Having eliminated all zero bytes from the data, a zero byte can now be "
    "used to unambiguously mark the end of the transformed data. This is done by appending "
    "a zero byte to the transformed data, thus forming a packet consisting of the "
    "COBS-encoded data (the payload) to unambiguously mark the end of the packet.\n"
    "\n"
    "(Any other byte value may be reserved as the packet delimiter, but using zero "
    "simplifies the description.)\n"
    "As a special exception, if a packet ends with a group of 254 non-zero bytes, it is "
    "not necessary to add the trailing zero byte. This saves one byte in some situations.\n"
    "\n"
    "Linked list description\n"
    "Example | Unencoded data (hex)\n"
    "| Data bytes | Encoded with COBS (hex)\n"
    "\n"
    "1 | 00\n"
    "| 1 | 01 01 00\n"
    "\n"
    "2 | 00 00\n"
    "| 2 | 01 01 01 00\n"
    "\n"
    "3 | 00 11 00\n"
    "| 3 | 01 02 11 01 00\n"
    "\n"
    "4 | 11 22 00 33\n"
    "| 4 | 03 11 22 02 33 00\n"
    "\n"
    "5 | 11 22 33 44\n"
    "| 4 | 05 11 22 33 44 00\n"
    "\n"
    "6 | 11 00 00 00\n"
    "| 4 | 02 11 01 01 01 00\n"
    "\n"
    "7 | 01 02 03 ... FD FE\n"
    "| 254 | FF 01 02 03 ... FD FE 00\n"
)
_R35_254 = " ".join(f"{b:02x}" for b in range(1, 255))
#: R35's final tests/cases.json, cases 1-8: empty_input's "00" equals its input and is
#: wrong; the six worked examples are right; 254_bytes_no_zero lacks the trailing 00.
R35_CASES = [
    {
        "name": "empty_input",
        "input": "00",
        "expected": "00",
        "source": [
            "COBS transforms an arbitrary string of bytes in the range [0,255] into bytes in "
            "the range [1,255]. Having eliminated all zero bytes from the data, a zero byte can "
            "now be used to unambiguously mark the end of the transformed data.",
            "As a special exception, if a packet ends with a group of 254 non-zero bytes, it is "
            "not necessary to add the trailing zero byte. This saves one byte in some situations.",
        ],
    },
    *(
        {
            "name": f"worked_example_{data.replace(' ', '_')}",
            "input": data,
            "expected": encoded,
            "source": [f"{row} | {data}", f"| {size} | {encoded}"],
        }
        for row, data, size, encoded in (
            (1, "00", 1, "01 01 00"),
            (2, "00 00", 2, "01 01 01 00"),
            (3, "00 11 00", 3, "01 02 11 01 00"),
            (4, "11 22 00 33", 4, "03 11 22 02 33 00"),
            (5, "11 22 33 44", 4, "05 11 22 33 44 00"),
            (6, "11 00 00 00", 4, "02 11 01 01 01 00"),
        )
    ),
    {
        "name": "254_bytes_no_zero",
        "input": _R35_254,
        "expected": f"ff {_R35_254}",
        "source": [
            "7 | 01 02 03 ... FD FE",
            "| 254 | FF 01 02 03 ... FD FE 00",
            "As a special exception, if a packet ends with a group of 254 non-zero bytes, it is "
            "not necessary to add the trailing zero byte. This saves one byte in some situations.",
        ],
    },
]


def _r35_reference() -> list[str]:
    module = _module()
    return [module._normalised(line) for line in R35_REFERENCE.splitlines() if line.strip()]


def test_short_result_checked_against_quoted_reference_line() -> None:
    # Audit 10: a result under RESULT_MIN_CHARS was never searched for, so R35's
    # "00" passed; now it must be on the quoted reference line or the next one.
    module = _module()
    reference = _r35_reference()
    assert len("01") < module.RESULT_MIN_CHARS
    held = {
        "on-line": {"in": [5], "expected": "01", "source": "| 1 | 01 01 00"},
        "next-line": {"in": [5], "expected": "44", "source": "| 4 | 03 11 22 02 33 00"},
        "number": {"in": [5], "expected": 1, "source": "| 1 | 01 01 00"},
        "quoted": {"in": [5], "expected": "33", "source": 'the row "4 | 11 22 00 33"'},
    }
    for name, case in held.items():
        assert not module._result_unquoted(case, [reference]), name
    wrong = {
        "absent": {"in": [5], "expected": "03", "source": "| 1 | 01 01 00"},
        "number": {"in": [5], "expected": 7, "source": "| 1 | 01 01 00"},
        "elsewhere": {"in": [5], "expected": "44", "source": "| 1 | 01 01 00"},
    }
    for name, case in wrong.items():
        assert module._result_unquoted(case, [reference]), name


def test_input_equal_result_checked_against_quoted_reference_line(tmp_path: Path) -> None:
    # R35: empty_input's expected "00" equalled its input, and its sources quoted
    # prose whose lines give no "00"; it is flagged, the six right worked examples
    # and a right 254-byte case in the elided form are not.
    module = _module()
    reference = _r35_reference()
    empty, *examples, short_254 = R35_CASES
    assert module._result_unquoted(empty, [reference])
    for case in examples:
        assert not module._result_unquoted(case, [reference]), case["name"]
    assert module._result_unquoted(short_254, [reference])
    right_254 = {**short_254, "expected": f"ff {_R35_254} 00"}
    assert not module._result_unquoted(right_254, [reference])
    on_line = {"input": "00 11 00", "expected": "00 11 00", "source": "3 | 00 11 00"}
    assert not module._result_unquoted(on_line, [reference])
    off_line = {"input": "00 11 00", "expected": "00 11 00", "source": "| 1 | 01 01 00"}
    assert module._result_unquoted(off_line, [reference])

    (tmp_path / "references").mkdir()
    (tmp_path / "references" / "cobs.txt").write_text(R35_REFERENCE)
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "cases.json").write_text(json.dumps(R35_CASES))
    found = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert found is not None
    assert found[:5] == ("tests/cases.json", 2, 8, ["empty_input", "254_bytes_no_zero"], True)
    (tmp_path / "tests" / "cases.json").write_text(json.dumps([*examples, right_254]))
    assert module._unquoted_cases(tmp_path, ["tests/cases.json"]) is None


def test_unquoted_cases_rejects_example_index_row_as_source(tmp_path: Path) -> None:
    # q35 R52: empty_input quoted "1 | 00", the example index and input of the
    # table's first row, as the source of a wrong expected [0], and was accepted.
    module = _module()
    reference = _r35_reference()
    wrong = {"name": "empty_input", "input": [], "expected": [0], "source": "1 | 00"}
    assert module._result_unquoted(wrong, [reference])
    assert module._result_unquoted({**wrong, "input": [17]}, [reference])
    right = [
        {"name": "single_zero", "input": [0], "expected": [1, 1, 0], "source": "1 | 00"},
        {
            "name": "two_zeros",
            "input": [0, 0],
            "expected": [1, 1, 1, 0],
            "source": "| 2 | 01 01 01 00",
        },
        {
            "name": "decode_zero_data_zero",
            "input": [1, 2, 17, 1, 0],
            "expected": [0, 17, 0],
            "source": "3 | 00 11 00",
        },
        {
            "name": "quoted_bytes",
            "input": [17, 34, 0, 51],
            "expected": [3, 17, 34, 2, 51, 0],
            "source": 'the row "| 4 | 03 11 22 02 33 00"',
        },
    ]
    for case in right:
        assert not module._result_unquoted(case, [reference]), case["name"]

    (tmp_path / "references").mkdir()
    (tmp_path / "references" / "cobs.txt").write_text(R35_REFERENCE)
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "cases.json").write_text(json.dumps([wrong, *right]))
    found = module._unquoted_cases(tmp_path, ["tests/cases.json"])
    assert found is not None
    assert found[:5] == ("tests/cases.json", 1, 5, ["empty_input"], True)
    assert "decode_zero_data_zero" in found[6] and "empty_input" not in found[6]
    (tmp_path / "tests" / "cases.json").write_text(json.dumps(right))
    assert module._unquoted_cases(tmp_path, ["tests/cases.json"]) is None


def test_short_result_with_no_quoted_context_is_not_flagged() -> None:
    # "1" or "ok" occurs in, or is absent from, unquoted text by chance: with no
    # reference line quoted there is nothing narrow to check it against.
    module = _module()
    reference = _r35_reference()
    for case in (
        {"in": [5], "expected": "1", "source": "prose without values"},
        {"in": [5], "expected": "ok", "source": "prose without values"},
        {"in": [5], "expected": 7, "source": "nothing the reference holds"},
        {"in": "00", "expected": "00", "source": "prose without values"},
        {"in": "00 11", "expected": "00 11", "source": "nothing the reference holds"},
    ):
        assert not module._result_unquoted(case, [reference]), case


@pytest.mark.anyio
async def test_locked_data_fix_proved_by_putting_back_committed(
    tmp_path: Path, beagle: Path, fake_beagle: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    # R34 E66: T0011 fixed the tracked, locked tests/cases.json; no file new since it
    # opened could be taken away, so `prove` was never even asked.
    project = _git_project(tmp_path, monkeypatch)
    locked = '[\n {"in": [0], "out": [1, 0]},\n {"in": [1], "out": [2, 1, 0]}\n]\n'
    (project / "tests").mkdir()
    (project / "tests" / "cases.json").write_text(locked)
    _git(project, "add", "tests")
    _git(project, "commit", "-q", "-m", "T0002: Known answers")
    _store_lock(project / ".beagle", "tests/cases.json", locked)
    fixed = locked.replace("[1, 0]", "[1, 1, 0]")
    (project / "tests" / "cases.json").write_text(fixed)
    opened = _git(project, "rev-parse", "HEAD").strip()
    record = {"id": "T0011", "status": "open", "opened_commit": opened}
    record["title"] = "Known answers: fix tests/cases.json"
    (fake_beagle / "show.out").write_text(json.dumps(record))
    module = _module()
    monkeypatch.setattr(module, "BEAGLE_BIN", str(fake_beagle / "beagle"))
    scope = ["tests/cases.json"]

    await module._prove("T0011", "done, no witness", scope, project, 60)

    prove = _pursuit_calls(fake_beagle, "prove")
    assert len(prove) == 1 and prove[0][:3] == ["T0011", "--mutate", "tests/cases.json"]
    needle = prove[0][prove[0].index("--needle") + 1]
    replacement = prove[0][prove[0].index("--replacement") + 1]
    assert fixed.count(needle) == 1 and fixed.replace(needle, replacement) == locked

    goal = project / ".beagle" / module.GOAL_BASENAME
    assert module._changed_locked_only(scope, goal, project) == ["tests/cases.json"]
    note = module._locked_data_proof_note(["tests/cases.json"])
    assert "must fail on the locked version of tests/cases.json" in note
    assert "absence is the proof" not in note
    record["title"] = "Implement the encoder"
    (fake_beagle / "show.out").write_text(json.dumps(record))
    assert module._locked_fix_reversion("T0011", ["src.py"], project, ["tests/cases.json"]) is None

    edits = [("a\nb\nc\n", "a\nB\nc\n"), ("x\nx\ny\n", "x\ny\n"), ("p\nq\n", "p\nq\nr\n")]
    for current, old in edits:
        edit = module._reversion_edit(current, old)
        assert edit is not None and current.count(edit[0]) == 1
        assert current.replace(edit[0], edit[1]) == old
    assert module._reversion_edit("same", "same") is None


@pytest.mark.anyio
@pytest.mark.parametrize("committed", [False, True])
async def test_close_next_step_agrees_with_already_passes(
    tmp_path: Path,
    beagle: Path,
    fake_beagle: Path,
    fake_tau: Path,
    monkeypatch: pytest.MonkeyPatch,
    committed: bool,
) -> None:
    # R34 E66-E68: the failed-prove close's Next named a check the next open
    # refused as "already passes, before any work".
    project = _witnessed_pursuit(tmp_path, monkeypatch)
    monkeypatch.chdir(project)
    _r21_tree(project)
    if committed:
        _commit(project, "tests/test_case_data.py", "tests/cases.json")
    _ready_task(fake_beagle, R21_CHECK)
    runtime, _ = _bound(tmp_path)
    step = _tool(runtime, "pursuit_step")
    scope = ["tests/test_case_data.py"]
    record = {"id": "T0002", "title": "Parser", "status": "open"}
    record |= {"done_when": R21_CHECK, "scope": scope}
    if committed:
        # Opened before the files were committed: the open's gate never ran.
        (fake_beagle / "show.out").write_text(json.dumps(record))
        (fake_beagle / "next.out").write_text(json.dumps({"open": [{"id": "T0002"}]}))
        args: dict[str, Any] = {"task": "T0002"}
    else:
        args = {"task": "T0002", "criteria": "c", "done_when": R21_CHECK, "scope": scope}

    first = await step.execute("c1", args)

    assert "no defect could be put back" in first.text, first.text
    kept = f"its done_when, `{R21_CHECK}`, which passes, kept" in first.text
    assert kept is not committed
    if committed:
        assert "refused as already passing" in first.text
        return
    (fake_beagle / "show.out").write_text(json.dumps(record))
    (fake_beagle / "next.out").write_text(json.dumps({"open": [{"id": "T0002"}], "ready": []}))
    route = {
        "task": "T0002",
        "new_route": True,
        "done_when": R21_CHECK,
        "scope": [*scope, "tests/cases.json"],
        "notes": "Add the data file the test reads to the scope.",
    }
    again = await step.execute("c2", route)
    assert "already passes" not in again.text, again.text


